local function mountOnTop(sg, order)
    sg.ResetOnSpawn = false
    sg.DisplayOrder = order or 1000000
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    pcall(function() sg.OnTopOfCoreBlur = true end)
    pcall(function()
