local _hubAnimToken = 0
local _hubShown = false
local reopenBtn
local function setHubVisible(v, fromUser)
    _hubAnimToken = _hubAnimToken + 1
    local token = _hubAnimToken
    v = v and true or false
    _hubShown = v
    -- Only mark "user hid hub" when the player toggles/closes it themselves.
    -- Intro/config/system reveals must not sticky-hide the next session.
    if fromUser == true then
        _G._VioletteccUserHidHub = (not v)
    end
    if reopenBtn and reopenBtn.Parent then reopenBtn.Visible = not v end
    if v then
        if gui and gui.Parent then gui.Enabled = true end
        outer.Visible = true
        panelPop.Scale = 0.92
        TweenService:Create(panelPop,
            TweenInfo.new(0.24, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
            {Scale = 1}):Play()
    else
        TweenService:Create(panelPop,
            TweenInfo.new(0.13, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
            {Scale = 0.92}):Play()
        task.delay(0.13, function()
            if token == _hubAnimToken then outer.Visible = false end
        end)
    end
end
_G._VioletteccSetHubVisible = setHubVisible
_G._VioletteccHubShown = function() return _hubShown end
_G._VioletteccUserHidHub = _G._VioletteccUserHidHub == true
-- Independent intro-completion reveal.  It lives next to the real GUI
-- objects, so an error in intro audio/animation cannot leave the whole hub
-- disabled forever.
local function forceVioletteHudReveal(soft)
    if not (gui and gui.Parent) then return end
    -- Always enable ScreenGui + steal bar (+ mobile policy).
    gui.Enabled = true
    local stealBar = gui:FindFirstChild("StealBar")
    if stealBar then stealBar.Visible = true end
    for _, d in ipairs(gui:GetDescendants()) do
        if d.Name == "StealBar" and d:IsA("GuiObject") then
            d.Visible = true
        end
    end
    if _G._VynxApplyHideMobile then
        pcall(_G._VynxApplyHideMobile, _G._VezyHideSideBtns == true)
    elseif _G._VezyMobileButtonsFrame then
        _G._VezyMobileButtonsFrame.Visible = (_G._VezyHideSideBtns ~= true)
    end

    -- Soft refreshes (delayed safety nets) must NEVER reopen the hub panel.
    if soft == true then
        return
    end

    if _G._VioletteccUserHidHub == true then
        if outer and outer.Parent then
            outer.Visible = false
            _hubShown = false
            if reopenBtn and reopenBtn.Parent then reopenBtn.Visible = true end
        end
        return
    end
    if outer and outer.Parent then
        outer.Visible = true
        panelPop.Scale = 1
        _hubShown = true
        if reopenBtn and reopenBtn.Parent then reopenBtn.Visible = false end
    end
end
_G._VioletteccForceHudReveal = forceVioletteHudReveal

