-- Background art is black + the original purple accent. Multiplying it by a
-- tint of (theme / purple), normalised so the brightest channel is 1, keeps
-- black as black and shifts the purple to the chosen theme color.
_G._VezyBgTintFor = function(accent)
    local ref = Color3.fromRGB(175, 95, 255)
    local r = accent.R / ref.R
    local g = accent.G / ref.G
    local b = accent.B / ref.B
    local m = math.max(r, g, b, 1e-4)
    return Color3.new(r / m, g / m, b / m)
end

-- Logo tint: same hue mapping as the backgrounds, lifted toward white so the
-- header stays vivid instead of dull (multiplying only ever darkens art).
_G._VezyLogoTintFor = function(accent)
    local h, sat = accent:ToHSV()
    return Color3.fromHSV(h, math.clamp(sat, 0.35, 0.7), 1)
end

-- Per-theme logo artwork. Paste the Roblox asset ID of each uploaded logo here.
-- A theme with an empty ID falls back to the Purple art tinted to that theme.
_G._VioletteccLogoIds = _G._VioletteccLogoIds or {
    Purple = "82846243064309",
    Red    = "90646849587381",
    Blue   = "71244408066405",
    Pink   = "135972675965246",
}
_G._VioletteccLogoThemeColors = {
    Purple = Color3.fromRGB(175, 95, 255),
    Red    = Color3.fromRGB(255, 72, 88),
    Blue   = Color3.fromRGB(55, 145, 255),
    Pink   = Color3.fromRGB(255, 110, 185),
}

-- Applies the right logo art (or tint fallback) for the accent to one ImageLabel
_G._VioletteccApplyLogoTheme = function(img, accent, instant)
    if not (img and img.Parent) then return end
    local ids = _G._VioletteccLogoIds
    local best, bestD = "Purple", math.huge
    for name, col in pairs(_G._VioletteccLogoThemeColors) do
        local d = (col.R - accent.R) ^ 2 + (col.G - accent.G) ^ 2 + (col.B - accent.B) ^ 2
        if d < bestD then best, bestD = name, d end
    end
    local id = ids[best]
    local hasArt = type(id) == "string" and id ~= ""
    img.Image = "rbxassetid://" .. (hasArt and id or ids.Purple)
    local color = hasArt and Color3.new(1, 1, 1) or _G._VezyLogoTintFor(accent)
    if instant then
        img.ImageColor3 = color
    else
        TweenService:Create(img, TweenInfo.new(0.25, Enum.EasingStyle.Quad), {ImageColor3 = color}):Play()
    end
end

