local function makeTab(name, order)
    local btn = Instance.new("TextButton", tabBar)
    btn.Size = UDim2.fromOffset(getMobileOptimized(68, 68), getMobileOptimized(34, 30))
    btn.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    btn.BackgroundTransparency = 0.45
    btn.BorderSizePixel = 0
    btn.Text = name
    btn.Font = Enum.Font.GothamBold
    btn.TextSize = getMobileOptimized(13, 12)
    btn.TextColor3 = Color3.fromRGB(220, 220, 230)
    btn.AutoButtonColor = false
    btn.LayoutOrder = order
    btn.ZIndex = 6
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 10)
    local st = Instance.new("UIStroke", btn)
    st.Name = "UIStroke"
    st.Color = Color3.fromRGB(38, 38, 42)
    st.Thickness = 1.0
    st.Transparency = 0.08
    st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    local sc = Instance.new("UIScale", btn)
    sc.Name = "TabPop"
    sc.Scale = 1

    local lbl = Instance.new("TextLabel", btn)
    lbl.Name = "Label"
    lbl.Size = UDim2.fromScale(1, 1)
    lbl.BackgroundTransparency = 1
    lbl.Text = ""
    lbl.TextTransparency = 1
    lbl.ZIndex = 7
    local underline = Instance.new("Frame", btn)
    underline.Name = "Underline"
    underline.BackgroundTransparency = 1
    underline.Size = UDim2.new(0, 0, 0, 0)

    btn.MouseEnter:Connect(function()
        if currentTab ~= name then
            TweenService:Create(btn, TweenInfo.new(0.14), {
                BackgroundTransparency = 0.45,
                TextColor3 = Color3.fromRGB(255, 255, 255),
            }):Play()
            TweenService:Create(st, TweenInfo.new(0.14), {Transparency = 0.03}):Play()
            TweenService:Create(sc, TweenInfo.new(0.14, Enum.EasingStyle.Back), {Scale = 1.05}):Play()
        end
    end)
    btn.MouseLeave:Connect(function()
        if currentTab ~= name then
            TweenService:Create(btn, TweenInfo.new(0.14), {
                BackgroundTransparency = 0.45,
                TextColor3 = Color3.fromRGB(220, 220, 230),
            }):Play()
            TweenService:Create(st, TweenInfo.new(0.14), {Transparency = 0.08}):Play()
            TweenService:Create(sc, TweenInfo.new(0.14), {Scale = 1}):Play()
        end
    end)
    -- Themes, hover and selected-state transitions must keep the same
    -- semi-transparent black tab surface.
    btn:GetPropertyChangedSignal("BackgroundTransparency"):Connect(function()
        if btn.BackgroundTransparency ~= 0.45 then btn.BackgroundTransparency = 0.45 end
    end)
    btn:GetPropertyChangedSignal("BackgroundColor3"):Connect(function()
        if btn.BackgroundColor3 ~= Color3.fromRGB(0,0,0) then btn.BackgroundColor3 = Color3.fromRGB(0,0,0) end
    end)

    tabButtons[name] = btn
    return btn
end


