local LP = LocalPlayer
-- ══ Spin Bot (ported from Glass Duels Hub) ══
_G._VioletteccSpinBotOn     = _G._VioletteccSpinBotOn == true
_G._VioletteccSpinBotSpeed  = tonumber(_G._VioletteccSpinBotSpeed)  or 360   -- deg/sec
_G._VioletteccSpinBotRadius = tonumber(_G._VioletteccSpinBotRadius) or 0     -- studs, 0 = spin in place
_G._VioletteccSpinBotAutoOnSteal = _G._VioletteccSpinBotAutoOnSteal == true
do
    local SPIN = { angle = 0, center = nil, conn = nil, prevAutoRotate = nil }

    local function stopLoop()
        if SPIN.conn then pcall(function() SPIN.conn:Disconnect() end); SPIN.conn = nil end
        local c = LP.Character
        local hum = c and c:FindFirstChildOfClass("Humanoid")
        if hum then
            local prev = SPIN.prevAutoRotate
            if prev == nil then prev = true end
            pcall(function() hum.AutoRotate = prev end)
        end
        SPIN.prevAutoRotate = nil
        local root = c and c:FindFirstChild("HumanoidRootPart")
        if root then pcall(function() root.AssemblyAngularVelocity = Vector3.zero end) end
    end

    local function startLoop()
        if SPIN.conn then return end
        SPIN.angle = 0
        local char = LP.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        local hum0 = char and char:FindFirstChildOfClass("Humanoid")
        if hrp then SPIN.center = hrp.Position end
        -- shiftlock / mouse-lock forces facing the camera: kill AutoRotate while spinning
        if hum0 then
            SPIN.prevAutoRotate = hum0.AutoRotate
            pcall(function() hum0.AutoRotate = false end)
        end
        SPIN.conn = RunService.RenderStepped:Connect(function(dt)
            if hubStale() then stopLoop(); return end
            if _G._VioletteccSpinBotOn ~= true then return end
            local c = LP.Character
            local root = c and c:FindFirstChild("HumanoidRootPart")
            local hum  = c and c:FindFirstChildOfClass("Humanoid")
            if not root or not hum or hum.Health <= 0 then return end
            pcall(function() hum.AutoRotate = false end)
            local spd = math.clamp(tonumber(_G._VioletteccSpinBotSpeed) or 360, 0, 2000)
            local rad = 0  -- radius option removed: always spin in place
            SPIN.angle = SPIN.angle + math.rad(spd) * dt
            if not SPIN.center then SPIN.center = root.Position end
            if rad <= 0.05 then
                local pos = root.Position
                SPIN.center = pos
                root.CFrame = CFrame.new(pos) * CFrame.Angles(0, -SPIN.angle, 0)
                local v = root.AssemblyLinearVelocity
                root.AssemblyAngularVelocity = Vector3.new(0, math.rad(spd), 0)
                root.AssemblyLinearVelocity  = v
            else
                local x = SPIN.center.X + math.cos(SPIN.angle) * rad
                local z = SPIN.center.Z + math.sin(SPIN.angle) * rad
                root.CFrame = CFrame.new(x, root.Position.Y, z) * CFrame.Angles(0, -SPIN.angle + math.rad(90), 0)
                root.AssemblyAngularVelocity = Vector3.new(0, math.rad(spd), 0)
                root.AssemblyLinearVelocity  = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
            end
        end)
    end

    -- Auto Spin on Steal (ported from Glass Duels Hub): spin ON while carrying a
    -- brainrot, OFF when it is dropped/collected or the round countdown starts.
    local function isHoldingAnimal()
        local char = LP.Character
        if not char then return false end
        if _G._CandyIsCarrying then
            local ok, v = pcall(_G._CandyIsCarrying, char)
            if ok and v then return true end
        end
        if _G._RaVeSafeMode and _G._RaVeSafeMode.HoldingBrainrot then
            local ok, v = pcall(_G._RaVeSafeMode.HoldingBrainrot)
            if ok and v then return true end
        end
        local ok1, v1 = pcall(function() return LP:GetAttribute("Stealing") end)
        if ok1 and v1 == true then return true end
        local ok2, v2 = pcall(function() return char:GetAttribute("Stealing") end)
        if ok2 and v2 == true then return true end
        return false
    end

    local function isRoundCountdown()
        if _G._RaVeSafeMode and _G._RaVeSafeMode.GetBlockReason then
            local ok, r = pcall(_G._RaVeSafeMode.GetBlockReason)
            if ok and type(r) == "string" and r:upper():find("COUNTDOWN") then return true end
        end
        return false
    end

    local function setSpin(on)
        if VisualSetters.SpinBot then
            pcall(VisualSetters.SpinBot, on)   -- updates the switch and runs its toggle callback
        end
        _G._VioletteccSpinBotOn = on and true or false
        if on then startLoop() else stopLoop() end
    end

    task.spawn(function()
        local wasHolding, autoWasOn = false, false
        while not hubStale() do
            task.wait(0.08)
            if _G._VioletteccSpinBotAutoOnSteal ~= true then
                wasHolding = false
                autoWasOn = false
            else
                local holding = isHoldingAnimal()
                local stop = isRoundCountdown()
                if holding and not stop and not wasHolding then
                    wasHolding = true
                    if _G._VioletteccSpinBotOn ~= true then
                        autoWasOn = true
                        setSpin(true)
                    else
                        autoWasOn = false  -- user already had it on: leave it alone
                    end
                elseif (not holding or stop) and wasHolding then
                    wasHolding = false
                    if autoWasOn then
                        autoWasOn = false
                        setSpin(false)
                    end
                end
            end
        end
    end)

    local charConn = LP.CharacterAdded:Connect(function()
        SPIN.center = nil
        if _G._VioletteccSpinBotOn == true then
            task.defer(function()
                task.wait(0.3)
                if _G._VioletteccSpinBotOn == true and not hubStale() then
                    stopLoop(); startLoop()
                end
            end)
        end
    end)

    _G._VioletteccStartSpinBot = startLoop
    _G._VioletteccStopSpinBot  = stopLoop
    _G._VioletteccSpinBotRuntime = {
        Destroy = function()
            _G._VioletteccSpinBotOn = false
            pcall(function() charConn:Disconnect() end)
            stopLoop()
        end,
    }
    _G._VioletteccSpinBotResetCenter = function()
        local r = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
        if r then SPIN.center = r.Position end
    end
end

