    local sSpin = TR(pMovement, 70, "Spin Bot", "", nil, _G._VioletteccSpinBotOn, function(on)
        _G._VioletteccSpinBotOn = on and true or false
        if on then
            if _G._VioletteccStartSpinBot then _G._VioletteccStartSpinBot() end
        else
            if _G._VioletteccStopSpinBot then _G._VioletteccStopSpinBot() end
        end
        -- Anti Die follows Spin Bot (on with it, off with it)
        if VisualSetters.AntiDie then
            pcall(VisualSetters.AntiDie, on and true or false)
        else
            _G._VynxAntiDie = on and true or false
        end
        if _G.KRIXSaveNow then pcall(_G.KRIXSaveNow) end
