task.defer(function()

    for _, child in ipairs(pMovement:GetChildren()) do
        if child:IsA("Frame") then
            for _, sub in ipairs(child:GetDescendants()) do
                if sub:IsA("TextLabel") and sub.Text == "Rotate Lock" then
