do
    local f = makeRowBase(pSteal, 32)
    nameWithUnderline(f, "Auto Steal")
    local setV = mkSwitch(f, Enabled.AutoSteal)
    _G._KRIXAutoStealSet = function(on) setV(on) end
    VisualSetters.AutoSteal = function(on) setV(on == true) end
    _G._VynxRefreshAutoSteal = function() setV(Enabled.AutoSteal == true) end
    local btn = Instance.new("TextButton", f)
    btn.Size = UDim2.new(1,0,1,0); btn.BackgroundTransparency = 1
    btn.Text = ""; btn.ZIndex = 8
    btn.MouseButton1Click:Connect(function()
        Enabled.AutoSteal = not Enabled.AutoSteal
        Settings.AutoStealEnabled = Enabled.AutoSteal
        setV(Enabled.AutoSteal)
        if Enabled.AutoSteal then startAutoSteal() else stopAutoSteal() end
        if _G.KRIXSaveNow then _G.KRIXSaveNow() end
    end)
    _G.VL.T["Auto Steal"] = { get = function() return Enabled.AutoSteal == true end,
        set = function(on)
            on = (on == true)
            if on == (Enabled.AutoSteal == true) then return end
            Enabled.AutoSteal = on
            Settings.AutoStealEnabled = on
            setV(on)
            if on then startAutoSteal() else stopAutoSteal() end
            if _G.KRIXSaveNow then _G.KRIXSaveNow() end
        end }
    _G.VL.rows[#_G.VL.rows + 1] = { kind = "T", key = "Auto Steal", name = "Auto Steal", page = pSteal, order = 32, def = (Enabled.AutoSteal == true), special = "steal" }
    _G._VynxNormalizeStealMode()
    -- Steal Mode dropdown removed (Semi disabled; Normal only)
    local _setModeDrop, _modePanel = nil, nil

    local function _applyGrabPausePct(raw)
        local pause = tonumber((tostring(raw or ""):gsub("%%", ""))) or tonumber(_G._VynxAutoGrabPause) or 75
        pause = math.clamp(math.floor(pause + 0.5), 73, 90)
        _G._VynxAutoGrabPause = pause
        local dur = tonumber(STEAL_DURATION_FIXED) or 1.30
        _G.K7NormalSteal = _G.K7NormalSteal or {}
        _G.K7NormalSteal.stopTime = dur * (pause / 100)
        _G.K7NormalSteal.stopEnabled = true
        return pause
    end

    local _pauseRow = makeRowBase(pSteal, 33)
    _pauseRow.Name = "AutoGrabPauseRow"
    nameWithUnderline(_pauseRow, "Grab Pause")

    local _pauseCustomTb
    local function _syncPauseCustomBox()
        if _pauseCustomTb then
            _pauseCustomTb.Text = tostring(tonumber(_G._VynxAutoGrabPause) or 75)
        end
    end

    local _setPauseDrop, _pausePanel = makeDropdown(_pauseRow, {"75%", "80%", "85%"},
        function()
            local p = tonumber(_G._VynxAutoGrabPause) or 75
            if p == 75 or p == 80 or p == 85 then return tostring(p) .. "%" end
            return tostring(p) .. "%"
        end,
        function(v)
            local pause = _applyGrabPausePct(v)
            _syncPauseCustomBox()
            if _setPauseDrop then pcall(_setPauseDrop) end
            if Enabled.AutoSteal then pcall(startAutoSteal) end
            if _G.KRIXSaveNow then pcall(_G.KRIXSaveNow) end
        end, 58, SW_W + 20, "Grab Pause")

    -- Typeable % box placed on the dropdown panel to the right of the 85% chip
    if _pausePanel then
        local customBx = Instance.new("Frame", _pausePanel)
        customBx.Name = "GrabPauseCustom"
        customBx.Size = UDim2.new(0, 44, 0, 24)
        -- Options are right-aligned: 85% is the rightmost chip; put box just to its right edge inset
        customBx.Position = UDim2.new(1, -12 - 44, 0.5, -12)
        customBx.BackgroundColor3 = BG_DARK
        customBx.BorderSizePixel = 0
        customBx.ZIndex = 6
        Instance.new("UICorner", customBx).CornerRadius = UDim.new(0, 8)
        local customSt = Instance.new("UIStroke", customBx)
        customSt.Color = ACC
        customSt.Thickness = 1
        customSt.Transparency = 0.45
        customSt.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        _pauseCustomTb = Instance.new("TextBox", customBx)
        _pauseCustomTb.Size = UDim2.new(1, 0, 1, 0)
        _pauseCustomTb.BackgroundTransparency = 1
        _pauseCustomTb.Text = tostring(tonumber(_G._VynxAutoGrabPause) or 75)
        _pauseCustomTb.TextColor3 = WHITE
        _pauseCustomTb.Font = Enum.Font.GothamBold
        _pauseCustomTb.TextSize = getMobileOptimized(11, 10)
        _pauseCustomTb.TextXAlignment = Enum.TextXAlignment.Center
        _pauseCustomTb.ClearTextOnFocus = false
        _pauseCustomTb.PlaceholderText = "73-90"
        _pauseCustomTb.PlaceholderColor3 = DIM
        _pauseCustomTb.ZIndex = 7
        _pauseCustomTb.FocusLost:Connect(function()
            local pause = _applyGrabPausePct(_pauseCustomTb.Text)
            _pauseCustomTb.Text = tostring(pause)
            if _setPauseDrop then pcall(_setPauseDrop) end
            if Enabled.AutoSteal then pcall(startAutoSteal) end
            if _G.KRIXSaveNow then pcall(_G.KRIXSaveNow) end
        end)

        -- Shift the 75/80/85 chips left to make room for the custom box
        task.defer(function()
            for _, ch in ipairs(_pausePanel:GetChildren()) do
                if ch:IsA("TextButton") and (ch.Text == "75%" or ch.Text == "80%" or ch.Text == "85%") then
                    local p = ch.Position
                    ch.Position = UDim2.new(p.X.Scale, p.X.Offset - 50, p.Y.Scale, p.Y.Offset)
                end
            end
        end)
    end

    local function _syncPauseRow()
        local isNormal = (_curStealMode() == "Normal")
        if _pauseRow then _pauseRow.Visible = isNormal end
        if _pausePanel and not isNormal then _pausePanel.Visible = false end
    end

    _G._VynxRefreshAutoGrabPause = function()
        _G._VynxNormalizeStealMode()
        local pause = _applyGrabPausePct(_G._VynxAutoGrabPause)
        _syncPauseCustomBox()
        if _setPauseDrop then pcall(_setPauseDrop) end
        _syncPauseRow()
    end

    _G._VynxRefreshAutoStealMode = function()
        _G._VynxNormalizeStealMode()
        if _setModeDrop then pcall(_setModeDrop) end
        if _G._VynxRefreshStealRadius then pcall(_G._VynxRefreshStealRadius) end
        if _G._VynxRefreshAutoGrabPause then pcall(_G._VynxRefreshAutoGrabPause) end
    end
    _G._VynxRefreshAutoGrabPause()
end

