    bg9  = Color3.fromRGB(175, 95, 255),
    bg10 = Color3.fromRGB(175, 95, 255),
}

_G._VioletteccAccent = ACC

-- ===== Theme color mapping =====
local ThemeMap = (function()
    local M = {}
    M.PURPLE = Color3.fromRGB(175, 95, 255)
    local TP_H, TP_S, TP_V = M.PURPLE:ToHSV()
    M.reg = setmetatable({}, {__mode = "k"})
    M.scanned = false
    -- Images/logos have their own tint logic and must not be hue-shifted here
    M.SKIP = {
        VioletteHeaderLogo = true, VioletteHeaderLogoGlow = true,
        VioletteHeaderLogoBoost = true, VioletteTitleImage = true,
        BackgroundImage = true,
    }

    function M.isPurpleish(c)
        local h, s, v = c:ToHSV()
        return h >= 0.68 and h <= 0.86 and s >= 0.2 and v >= 0.25
    end

    -- Moves a purple shade to the theme hue, keeping its lightness/saturation feel
    function M.target(orig, theme)
        if orig == M.PURPLE then return theme end
        local h, s, v = orig:ToHSV()
        local th, ts, tv = theme:ToHSV()
        return Color3.fromHSV((h - TP_H + th) % 1,
            math.clamp(s * ts / TP_S, 0, 1),
            math.clamp(v * tv / TP_V, 0, 1))
    end

    local function seqEqual(seq, kps)
        local a = seq.Keypoints
        if #a ~= #kps then return false end
        for i, kp in ipairs(a) do
            if kp.Value ~= kps[i].Value then return false end
        end
        return true
    end

    function M.repaintGradient(g, old, theme, canRegister)
        local entry = M.reg[g]
        if not entry then
            local has = false
            for _, kp in ipairs(g.Color.Keypoints) do
                if kp.Value == old or (canRegister and M.isPurpleish(kp.Value)) then has = true break end
            end
            if not has then return end
            local origKps = {}
            for i, kp in ipairs(g.Color.Keypoints) do
                origKps[i] = {Time = kp.Time, Value = (kp.Value == old) and M.PURPLE or kp.Value}
            end
            entry = {orig = origKps, last = g.Color.Keypoints}
            M.reg[g] = entry
        elseif not seqEqual(g.Color, entry.last) then
            return
        end
        local out = {}
        for i, kp in ipairs(entry.orig) do
            local v = kp.Value
            if v == M.PURPLE or M.isPurpleish(v) then v = M.target(v, theme) end
            out[i] = ColorSequenceKeypoint.new(kp.Time, v)
        end
        g.Color = ColorSequence.new(out)
        entry.last = g.Color.Keypoints
    end
    return M
end)()

local function applyAccent(newColor)
    if typeof(newColor) ~= "Color3" then return end
    local old = _G._VioletteccAccent or ACC
    if newColor == old then return end

    -- Every purple-toned color in the menu (accent, light text, dark panels)
    -- is hue-shifted to the chosen theme, not just exact accent matches.
    local firstPass = not ThemeMap.scanned
    ThemeMap.scanned = true
    local oldIsPurple = (old == ThemeMap.PURPLE)

    local function repaint(inst, prop)
        local ok, cur = pcall(function() return inst[prop] end)
        if not ok or typeof(cur) ~= "Color3" then return end
        local reg = ThemeMap.reg[inst]
        if not reg then reg = {}; ThemeMap.reg[inst] = reg end
        local entry = reg[prop]
        if not entry then
            if cur == old then
                entry = {orig = ThemeMap.PURPLE, last = cur}
            elseif firstPass and oldIsPurple and ThemeMap.isPurpleish(cur) then
                entry = {orig = cur, last = cur}
            else
                return
            end
            reg[prop] = entry
        elseif cur ~= entry.last and cur ~= old then
            return -- changed by other code (e.g. a toggle going gray); leave it
        end
        pcall(function()
            inst[prop] = ThemeMap.target(entry.orig, newColor)
            entry.last = inst[prop]
        end)
    end

    for _, d in ipairs(gui:GetDescendants()) do
        pcall(function()
            if d:IsA("UIStroke") then
                repaint(d, "Color")
            elseif d:IsA("UIGradient") then
                ThemeMap.repaintGradient(d, old, newColor, firstPass and oldIsPurple)
            elseif d:IsA("GuiObject") then
                if not ThemeMap.SKIP[d.Name] then
                    repaint(d, "BackgroundColor3")
                    repaint(d, "BorderColor3")
                    if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then
                        repaint(d, "TextColor3")
                    end
                    if d:IsA("ScrollingFrame") then
                        repaint(d, "ScrollBarImageColor3")
                    end
                end
            end
        end)
    end

    ACC = newColor
    _G._VioletteccAccent = newColor
    -- Header logo + reopen-button logo follow the selected theme color
    local logoTween = TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
    local function tintLogo(img)
        if img and img.Parent then
            img.BackgroundTransparency = 1
            _G._VioletteccApplyLogoTheme(img, newColor, false)
        end
    end
    for _, letter in ipairs(hdrWordmark) do tintLogo(letter) end
    tintLogo(gui:FindFirstChild("VioletteTitleImage", true))
    if _G._VezyRefreshBgTint then pcall(_G._VezyRefreshBgTint, newColor) end
    if _G._VynxRefreshMobileBtnColors then pcall(_G._VynxRefreshMobileBtnColors) end
    if _G._VioletteccRepaintTabs then pcall(_G._VioletteccRepaintTabs) end
    if _G._VioletteccSetTagColor then pcall(_G._VioletteccSetTagColor, newColor) end
    if _G._VioletteccRefreshAvatarESPColor then pcall(_G._VioletteccRefreshAvatarESPColor) end
    if _G._VioletteccRefreshRagdollCDColor then pcall(_G._VioletteccRefreshRagdollCDColor) end
    if _G._AdaptRefreshESPColor then pcall(_G._AdaptRefreshESPColor, newColor) end
    if _G._VioletteccRefreshPanels then pcall(_G._VioletteccRefreshPanels) end
end

_G._VioletteccApplyAccent = applyAccent
-- Maps any original purple shade to the active theme (used by buttons, billboards)
_G._VioletteccThemeColor = function(c)
    return ThemeMap.target(c, _G._VioletteccAccent or ACC)
end
_G._VioletteccAccentForBg = function(key)
    return BG_ACCENTS[key or "off"] or BG_ACCENTS.off
end

