    local themeChips = {}
    local function refreshThemeChips()
        local cur = tostring(_G._VioletteccThemeName or "Purple")
        for name, btn in pairs(themeChips) do
            local on = (name == cur)
            local col = THEME_COLORS[name]
            btn.BackgroundColor3 = on and col or Color3.fromRGB(30, 30, 34)
            btn.TextColor3 = on and Color3.fromRGB(12, 10, 16) or Color3.fromRGB(180, 180, 190)
            local st = btn:FindFirstChildOfClass("UIStroke")
            if st and col then
                st.Color = col
                st.Transparency = on and 0.1 or 0.45
            end
        end
    end

    local function setTheme(name)
        name = THEME_COLORS[name] and name or "Purple"
        _G._VioletteccThemeName = name
        local col = THEME_COLORS[name]
        if col and _G._VioletteccApplyAccent then
            pcall(_G._VioletteccApplyAccent, col)
        elseif col then
            applyAccent(col)
        end
        refreshThemeChips()
        if _G.KRIXSaveNow then pcall(_G.KRIXSaveNow) end
    end

    for i, name in ipairs(THEME_ORDER) do
