_G._VioletteccPingLaggerUI = (function()
-- Violette Ping Lagger + Auto Brainrot
-- PC + Controller keybind | Customizable | Auto-save | Background picker | Strength presets | V1/V2 modes

local UserInputService = game:GetService("UserInputService")
local TweenService     = game:GetService("TweenService")
local HttpService      = game:GetService("HttpService")
local Players          = game:GetService("Players")
local RunService       = game:GetService("RunService")

local plr    = Players.LocalPlayer
local plrGui = plr:WaitForChild("PlayerGui")

-- ══════════════════════════════════════════════════════════════════════
-- CONFIG & SAVE
-- ══════════════════════════════════════════════════════════════════════
local CONFIG_FILE = "ViolettePingLagger_Config.json"

local BG_OPTIONS = {
	{ key = "off", label = "None", id = "" },
	{ key = "bg1", label = "BG 1", id = "71792293290595" },
	{ key = "bg4", label = "BG 4", id = "125423918880160" },
	{ key = "bg6", label = "BG 6", id = "119934726907659" },
	{ key = "bg8", label = "BG 8", id = "121229055542067" },
}

-- Strength presets: depth = nesting layers inside each rep, scale = rep-count multiplier
local STRENGTH_OPTIONS = {
	{ key = "ultraweak",   label = "Ultra Weak",   depth = 155, scale = 0.17 },
	{ key = "extraweak",   label = "Extra Weak",   depth = 160, scale = 0.34 },
	{ key = "weak",        label = "Weak",         depth = 170, scale = 0.68 },
	{ key = "normal",      label = "Normal",       depth = 186, scale = 1.00 },
	{ key = "strong",      label = "Strong",       depth = 200, scale = 1.38 },
	{ key = "extrastrong", label = "Extra Strong", depth = 215, scale = 2.06 },
	{ key = "ultrastrong", label = "Ultra Strong", depth = 230, scale = 2.75 },
}

local DEFAULT_CFG = {
	power        = 100000,
	interval     = 0.125,
	keybindKb    = "F",
	keybindGp    = "ButtonR2",
	autoBrainrot = true,
	backgroundId = "71792293290595",
	strength     = "normal",
	mode         = "v1",
	locked       = false,
}

local cfg = {
	power        = DEFAULT_CFG.power,
	interval     = DEFAULT_CFG.interval,
	keybindKb    = DEFAULT_CFG.keybindKb,
	keybindGp    = DEFAULT_CFG.keybindGp,
	autoBrainrot = DEFAULT_CFG.autoBrainrot,
	backgroundId = DEFAULT_CFG.backgroundId,
	strength     = DEFAULT_CFG.strength,
	mode         = DEFAULT_CFG.mode,
	locked       = DEFAULT_CFG.locked,
}

-- ══════════════════════════════════════════════════════════════════════
-- STRENGTH HELPERS (must live AFTER cfg is declared)
-- ══════════════════════════════════════════════════════════════════════
local function getStrengthPreset()
	for _, o in ipairs(STRENGTH_OPTIONS) do
		if o.key == cfg.strength then return o end
	end
	return STRENGTH_OPTIONS[4] -- Normal
end

local function getStrengthLabel()
	for _, o in ipairs(STRENGTH_OPTIONS) do
		if o.key == cfg.strength then return o.label end
	end
	return "Normal"
end

local function resolveKb(name)
	if not name or name == "" or name == "None" then return nil end
	local ok, val = pcall(function() return Enum.KeyCode[name] end)
	return (ok and val) or nil
end

local function saveConfig()
	local ok, encoded = pcall(function() return HttpService:JSONEncode(cfg) end)
	if ok and encoded and writefile then
		pcall(writefile, CONFIG_FILE, encoded)
	end
end

local function loadConfig()
	if not (isfile and readfile and isfile(CONFIG_FILE)) then return end
	local ok, data = pcall(function() return HttpService:JSONDecode(readfile(CONFIG_FILE)) end)
	if not ok or type(data) ~= "table" then return end

	cfg.power        = tonumber(data.power) or DEFAULT_CFG.power
	cfg.interval     = tonumber(data.interval) or DEFAULT_CFG.interval
	cfg.keybindKb    = type(data.keybindKb) == "string" and data.keybindKb or DEFAULT_CFG.keybindKb
	cfg.keybindGp    = type(data.keybindGp) == "string" and data.keybindGp or DEFAULT_CFG.keybindGp
	if type(data.autoBrainrot) == "boolean" then cfg.autoBrainrot = data.autoBrainrot end
	cfg.backgroundId = type(data.backgroundId) == "string" and data.backgroundId or DEFAULT_CFG.backgroundId
	cfg.strength     = type(data.strength) == "string" and data.strength or DEFAULT_CFG.strength
	cfg.mode         = type(data.mode) == "string" and data.mode or DEFAULT_CFG.mode
	cfg.locked       = data.locked == true
end

loadConfig()

local panelOpen         = false   -- only react to keys / auto-brainrot while the panel is open
