local function applyBackground(id, targets)
	cfg.backgroundId = tostring(id or "")
	for _, img in ipairs(targets) do
		if cfg.backgroundId == "" then
			img.Image = ""
			img.Visible = false
		else
			img.Image = "rbxassetid://" .. cfg.backgroundId
			img.Visible = true
		end
	end
end

