local function paintLock(animate)
	local on = cfg.locked == true
	lockBtn.Text = on and "🔒" or "🔓"
	lockBtn.TextColor3 = on and Color3.fromRGB(0, 0, 0) or C.dim
	local bg = on and C.accent or C.card
	if animate then tw(lockBtn, { BackgroundColor3 = bg }) else lockBtn.BackgroundColor3 = bg end
end
paintLock(false)

lockBtn.MouseEnter:Connect(function()
	if not cfg.locked then tw(lockBtn, { BackgroundColor3 = C.card2 }) end
end)
lockBtn.MouseLeave:Connect(function() paintLock(true) end)
lockBtn.MouseButton1Click:Connect(function()
	cfg.locked = not cfg.locked
	paintLock(true)
	saveConfig()
end)

