-- Input row
local function mkInputRow(yPos, labelText, getValue, onConfirm)
	local row = Instance.new("Frame", settingsFrame)
	row.Size = UDim2.new(1, -20, 0, 36)
	row.Position = UDim2.new(0, 10, 0, yPos)
	row.BackgroundColor3 = C.card
	row.BorderSizePixel = 0
	row.ZIndex = 22
	corner(row, 10)
	stroke(row, C.edge, 1, 0.25)

	local lbl = Instance.new("TextLabel", row)
	lbl.Size = UDim2.new(0.5, 0, 1, 0)
	lbl.Position = UDim2.new(0, 12, 0, 0)
	lbl.BackgroundTransparency = 1
	lbl.Text = labelText
	lbl.TextColor3 = C.white
	lbl.Font = Enum.Font.GothamBold
	lbl.TextSize = 11
	lbl.TextXAlignment = Enum.TextXAlignment.Left
	lbl.ZIndex = 23

	local box = Instance.new("TextBox", row)
	box.Size = UDim2.fromOffset(68, 24)
	box.Position = UDim2.new(1, -78, 0.5, -12)
	box.BackgroundColor3 = C.inputBg
	box.BorderSizePixel = 0
	box.Text = tostring(getValue())
	box.TextColor3 = C.accent
	box.Font = Enum.Font.GothamBold
	box.TextSize = 11
	box.ClearTextOnFocus = false
	box.ZIndex = 24
	corner(box, 7)
	local bs = stroke(box, C.accent, 1, 0.55)

	box.Focused:Connect(function()
		tw(bs, { Transparency = 0.1 })
	end)
	box.FocusLost:Connect(function()
		tw(bs, { Transparency = 0.55 })
		local n = tonumber(box.Text)
		if n then
			onConfirm(n)
			box.Text = tostring(getValue())
			saveConfig()
		else
			box.Text = tostring(getValue())
		end
	end)
	return box
end

local kbBindBtn, gpBindBtn

local function updateKbLabels()
	if kbBindBtn then
		if listeningFor == "kb" then
			kbBindBtn.Text = "..."
			kbBindBtn.TextColor3 = C.waiting
		else
			kbBindBtn.Text = cfg.keybindKb ~= "" and cfg.keybindKb or "None"
			kbBindBtn.TextColor3 = C.accent
		end
	end
	if gpBindBtn then
		if listeningFor == "gp" then
			gpBindBtn.Text = "..."
			gpBindBtn.TextColor3 = C.waiting
		else
			gpBindBtn.Text = cfg.keybindGp ~= "" and cfg.keybindGp or "None"
			gpBindBtn.TextColor3 = C.accent
		end
	end
end

local function mkKeybindRow(yPos, labelText, which)
	local row = Instance.new("Frame", settingsFrame)
	row.Size = UDim2.new(1, -20, 0, 36)
	row.Position = UDim2.new(0, 10, 0, yPos)
	row.BackgroundColor3 = C.card
	row.BorderSizePixel = 0
	row.ZIndex = 22
	corner(row, 10)
	stroke(row, C.edge, 1, 0.25)

	local lbl = Instance.new("TextLabel", row)
	lbl.Size = UDim2.new(0.4, 0, 1, 0)
	lbl.Position = UDim2.new(0, 12, 0, 0)
	lbl.BackgroundTransparency = 1
	lbl.Text = labelText
	lbl.TextColor3 = C.white
	lbl.Font = Enum.Font.GothamBold
	lbl.TextSize = 11
	lbl.TextXAlignment = Enum.TextXAlignment.Left
	lbl.ZIndex = 23

	local bindBtn = Instance.new("TextButton", row)
	bindBtn.Size = UDim2.fromOffset(78, 24)
	bindBtn.Position = UDim2.new(1, -112, 0.5, -12)
	bindBtn.BackgroundColor3 = C.inputBg
	bindBtn.BorderSizePixel = 0
	bindBtn.AutoButtonColor = false
	bindBtn.Font = Enum.Font.GothamBold
	bindBtn.TextSize = 10
	bindBtn.TextColor3 = C.accent
	bindBtn.ZIndex = 24
	bindBtn.Text = which == "kb" and cfg.keybindKb or cfg.keybindGp
	corner(bindBtn, 7)
	local bStr = stroke(bindBtn, C.accent, 1, 0.55)

	bindBtn.MouseEnter:Connect(function() tw(bStr, { Transparency = 0.1 }) end)
	bindBtn.MouseLeave:Connect(function() tw(bStr, { Transparency = 0.55 }) end)
	bindBtn.MouseButton1Click:Connect(function()
		listeningFor = (listeningFor == which) and nil or which
		updateKbLabels()
	end)

	local clearBtn = Instance.new("TextButton", row)
	clearBtn.Size = UDim2.fromOffset(24, 24)
	clearBtn.Position = UDim2.new(1, -30, 0.5, -12)
	clearBtn.BackgroundColor3 = Color3.fromRGB(36, 18, 22)
	clearBtn.BorderSizePixel = 0
	clearBtn.AutoButtonColor = false
	clearBtn.Text = "X"
	clearBtn.TextColor3 = C.red
	clearBtn.Font = Enum.Font.GothamBlack
	clearBtn.TextSize = 12
	clearBtn.ZIndex = 24
	corner(clearBtn, 7)

	clearBtn.MouseButton1Click:Connect(function()
		if listeningFor == which then listeningFor = nil end
		if which == "kb" then cfg.keybindKb = "None" else cfg.keybindGp = "None" end
		updateKbLabels()
		saveConfig()
	end)

	if which == "kb" then kbBindBtn = bindBtn end
	if which == "gp" then gpBindBtn = bindBtn end
	return bindBtn
end

