	lbl.ZIndex = 23

	local prevBtn = Instance.new("TextButton", row)
	prevBtn.Size = UDim2.fromOffset(22, 24)
	prevBtn.Position = UDim2.new(1, -172, 0.5, -12)
	prevBtn.BackgroundColor3 = C.inputBg
	prevBtn.BorderSizePixel = 0
	prevBtn.AutoButtonColor = false
	prevBtn.Text = "<"
	prevBtn.TextColor3 = C.accent
	prevBtn.Font = Enum.Font.GothamBlack
	prevBtn.TextSize = 12
	prevBtn.ZIndex = 24
	corner(prevBtn, 7)
	local ps = stroke(prevBtn, C.accent, 1, 0.55)
	prevBtn.MouseEnter:Connect(function() tw(ps, { Transparency = 0.1 }) end)
	prevBtn.MouseLeave:Connect(function() tw(ps, { Transparency = 0.55 }) end)

	local cycleBtn = Instance.new("TextButton", row)
	cycleBtn.Size = UDim2.fromOffset(106, 24)
	cycleBtn.Position = UDim2.new(1, -148, 0.5, -12)
	cycleBtn.BackgroundColor3 = C.inputBg
	cycleBtn.BorderSizePixel = 0
	cycleBtn.AutoButtonColor = false
	cycleBtn.Text = getStrengthLabel()
	cycleBtn.TextColor3 = C.accent
	cycleBtn.Font = Enum.Font.GothamBold
	cycleBtn.TextSize = 10
	cycleBtn.ZIndex = 24
	corner(cycleBtn, 7)
	local cs = stroke(cycleBtn, C.accent, 1, 0.55)
	cycleBtn.MouseEnter:Connect(function() tw(cs, { Transparency = 0.1 }) end)
	cycleBtn.MouseLeave:Connect(function() tw(cs, { Transparency = 0.55 }) end)

	local nextBtn = Instance.new("TextButton", row)
	nextBtn.Size = UDim2.fromOffset(22, 24)
	nextBtn.Position = UDim2.new(1, -40, 0.5, -12)
	nextBtn.BackgroundColor3 = C.inputBg
	nextBtn.BorderSizePixel = 0
	nextBtn.AutoButtonColor = false
	nextBtn.Text = ">"
	nextBtn.TextColor3 = C.accent
	nextBtn.Font = Enum.Font.GothamBlack
	nextBtn.TextSize = 12
	nextBtn.ZIndex = 24
	corner(nextBtn, 7)
	local ns = stroke(nextBtn, C.accent, 1, 0.55)
	nextBtn.MouseEnter:Connect(function() tw(ns, { Transparency = 0.1 }) end)
	nextBtn.MouseLeave:Connect(function() tw(ns, { Transparency = 0.55 }) end)

	local function currentIndex()
		for i, o in ipairs(STRENGTH_OPTIONS) do
			if o.key == cfg.strength then return i end
		end
		return 4
	end

	local function apply()
		local preset = STRENGTH_OPTIONS[currentIndex()]
		cfg.strength = preset.key
		cycleBtn.Text = preset.label
		saveConfig()
	end

	prevBtn.MouseButton1Click:Connect(function()
		local i = currentIndex() - 1
		if i < 1 then i = #STRENGTH_OPTIONS end
		cfg.strength = STRENGTH_OPTIONS[i].key
		apply()
	end)

	nextBtn.MouseButton1Click:Connect(function()
		local i = currentIndex() + 1
		if i > #STRENGTH_OPTIONS then i = 1 end
		cfg.strength = STRENGTH_OPTIONS[i].key
		apply()
	end)

	cycleBtn.MouseButton1Click:Connect(function()
		local i = currentIndex() + 1
		if i > #STRENGTH_OPTIONS then i = 1 end
		cfg.strength = STRENGTH_OPTIONS[i].key
		apply()
	end)

	strengthBtn = cycleBtn
	return cycleBtn
end

-- V1 / V2 mode picker
local v1Btn, v2Btn

local function createModeRow(yPos)
	local row = Instance.new("Frame", settingsFrame)
	row.Size = UDim2.new(1, -20, 0, 36)
	row.Position = UDim2.new(0, 10, 0, yPos)
	row.BackgroundColor3 = C.card
	row.BorderSizePixel = 0
	row.ZIndex = 22
	corner(row, 10)
	stroke(row, C.edge, 1, 0.25)

	local lbl = Instance.new("TextLabel", row)
	lbl.Size = UDim2.new(0.42, 0, 1, 0)
	lbl.Position = UDim2.new(0, 12, 0, 0)
	lbl.BackgroundTransparency = 1
	lbl.Text = "Mode"
	lbl.TextColor3 = C.white
	lbl.Font = Enum.Font.GothamBold
	lbl.TextSize = 11
	lbl.TextXAlignment = Enum.TextXAlignment.Left
	lbl.ZIndex = 23

	local function makeModeBtn(text, key, xPos)
		local b = Instance.new("TextButton", row)
		b.Size = UDim2.fromOffset(64, 24)
		b.Position = UDim2.new(1, xPos, 0.5, -12)
		b.BackgroundColor3 = C.inputBg
		b.BorderSizePixel = 0
		b.AutoButtonColor = false
		b.Text = text
		b.Font = Enum.Font.GothamBlack
		b.TextSize = 11
		b.ZIndex = 24
		corner(b, 7)
		stroke(b, C.edge, 1, 0.3)

		b.MouseButton1Click:Connect(function()
			cfg.mode = key
			saveConfig()
			local on1 = cfg.mode == "v1"
			local on2 = cfg.mode == "v2"
			if v1Btn then
				v1Btn.BackgroundColor3 = on1 and C.accent or C.inputBg
				v1Btn.TextColor3 = on1 and Color3.fromRGB(0, 0, 0) or C.accent
			end
			if v2Btn then
				v2Btn.BackgroundColor3 = on2 and C.accent or C.inputBg
				v2Btn.TextColor3 = on2 and Color3.fromRGB(0, 0, 0) or C.accent
			end
		end)

		return b
	end

	v1Btn = makeModeBtn("V1", "v1", -142)
	v2Btn = makeModeBtn("V2", "v2", -74)
	return v1Btn, v2Btn
end

local function refreshModeButtons()
	local on1 = cfg.mode == "v1"
	local on2 = cfg.mode == "v2"
	if v1Btn then
		v1Btn.BackgroundColor3 = on1 and C.accent or C.inputBg
		v1Btn.TextColor3 = on1 and Color3.fromRGB(0, 0, 0) or C.accent
	end
	if v2Btn then
		v2Btn.BackgroundColor3 = on2 and C.accent or C.inputBg
		v2Btn.TextColor3 = on2 and Color3.fromRGB(0, 0, 0) or C.accent
	end
end

