			off.Size = UDim2.fromScale(1, 1)
			off.BackgroundTransparency = 1
			off.Text = "Off"
			off.TextColor3 = C.dim
			off.Font = Enum.Font.GothamBold
			off.TextSize = 10
			off.ZIndex = 25
		end

		btn.MouseButton1Click:Connect(function()
			applyBackground(opt.id, { mainBg, setBg })
			refresh()
			saveConfig()
		end)

		refs[#refs + 1] = { id = opt.id, stroke = st }
	end

	refresh()
	return refresh
end

