	local function setVisual(state)
		local targetPos = state and UDim2.new(1, -19, 0.5, -8) or UDim2.new(0, 3, 0.5, -8)
		local targetBg = state and colors.accent or colors.toggleOff
		TweenService:Create(dot, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
			Position = targetPos,
		}):Play()
		TweenService:Create(bgToggle, TweenInfo.new(0.16), { BackgroundColor3 = targetBg }):Play()
	end

	click.MouseButton1Click:Connect(function()
		onToggle()
		local state = (labelText == "Anti Bat" and antiBatActive) or (labelText == "Inf Jump" and infJumpActive)
		setVisual(state)
		updateStatus()
		saveConfig()
	end)

	return setVisual
end

