            dragging = true
            dragStart = input.Position
            startPos = MiniFrame.Position
        end
    end)
    _conns[#_conns + 1] = UserInputService.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local d = input.Position - dragStart
            MiniFrame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
        end
    end)
    _conns[#_conns + 1] = UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end)
end

local function applyVisibility()
    MainFrame.Visible = panelOpen and not State.Compact
    MiniFrame.Visible = panelOpen and State.Compact
end

setCompact = function(on, skipSave)
    on = on == true
    State.Compact = on
    if on then
        MiniFrame.Position = MainFrame.Position
    else
        MainFrame.Position = MiniFrame.Position
    end
    applyVisibility()
    updateMiniVisual()
    if not skipSave then saveData() end
end

do
    local dragging = false
    local dragStart, startPos

    local function startDrag(input)
        dragging = true
        dragStart = input.Position
        startPos = MainFrame.Position
    end

    local function updateDrag(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local delta = input.Position - dragStart
            MainFrame.Position = UDim2.new(
                startPos.X.Scale, startPos.X.Offset + delta.X,
                startPos.Y.Scale, startPos.Y.Offset + delta.Y
            )
        end
    end

    local function endDrag()
        dragging = false
    end

    TitleBar.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            startDrag(input)
        end
    end)

    _conns[#_conns + 1] = UserInputService.InputChanged:Connect(updateDrag)

    _conns[#_conns + 1] = UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            endDrag()
        end
    end)
end

local function checkAutoWalkSpeed()
    if not State.AutoEnable then
        if State.AutoActive then
            State.AutoActive = false
            setEnabled(false)
        end
        return
    end

    local char = LocalPlayer.Character
    if not char then
        if State.AutoActive then
            State.AutoActive = false
            setEnabled(false)
        end
        return
    end

    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then
        if State.AutoActive then
            State.AutoActive = false
            setEnabled(false)
        end
        return
    end

    local ws = hum.WalkSpeed
    local inRange = ws >= AUTO_MIN_WS and ws <= AUTO_MAX_WS

    if inRange and not State.Enabled then
        State.AutoActive = true
        setEnabled(true)
    elseif not inRange and State.Enabled and State.AutoActive then
        State.AutoActive = false
        setEnabled(false)
    end
end

local function autoSave()
    saveTimer = saveTimer + 1
    if saveTimer >= saveInterval then
        saveTimer = 0
        saveData()
    end
end

_conns[#_conns + 1] = RunService.Heartbeat:Connect(function()
    autoSave()
    checkAutoWalkSpeed()
    if not remote then
        remote = findRemote()
    end
end)

_conns[#_conns + 1] = UserInputService.InputBegan:Connect(function(input, gameProcessed)
    if State.Listening then
        if input.UserInputType == Enum.UserInputType.Keyboard or input.UserInputType == Enum.UserInputType.Gamepad1 then
            if input.KeyCode ~= Enum.KeyCode.Unknown then
                State.Keybind = input.KeyCode
                if KeybindButton then KeybindButton.Text = input.KeyCode.Name end
                State.Listening = false
                saveData()
            end
        end
        return
    end
    if gameProcessed then return end
    if State.Keybind and input.KeyCode == State.Keybind then
        toggleEnabled()
    end
end)

updateAccentTheme = function(previousAccent, previousAccentDim)
    for _, object in ipairs(MainFrame:GetDescendants()) do
        if object:IsA("UIStroke") then
            if object.Color == previousAccent then
                object.Color = Theme.Accent
            elseif object.Color == previousAccentDim then
                object.Color = Theme.AccentDim
            end
        elseif object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
            if object.TextColor3 == previousAccent then
                object.TextColor3 = Theme.Accent
            end
        elseif object:IsA("GuiObject") then
            if object.BackgroundColor3 == previousAccent then
                object.BackgroundColor3 = Theme.Accent
            elseif object.BackgroundColor3 == previousAccentDim then
                object.BackgroundColor3 = Theme.AccentDim
            end
        end
    end

    applyModeVisual()
    applyStartVisual()
    updateToggleVisual()
end

loadData()
setBackground(State.BackgroundIndex)
GuiScale.Scale = State.GuiSize
updateSizeLabel()
applyModeVisual()
applyStartVisual()
updateSliderVisual()
updateToggleVisual()
PowerInput.Text = tostring(State.Power)
if State.Keybind and KeybindButton then
    KeybindButton.Text = State.Keybind.Name
end
setCompact(State.Compact, true)

local function setOpen(on)
    on = on == true
    if panelOpen == on then return end
    panelOpen = on
    applyVisibility()
end

return {
    Toggle = function() setOpen(not panelOpen); return panelOpen end,
    IsOpen = function() return panelOpen end,
    SetOpen = setOpen,
    Destroy = function()
        pcall(function() if State.Enabled then setEnabled(false) end end)
        for _, c in ipairs(_conns) do pcall(function() c:Disconnect() end) end
        _conns = {}
        pcall(function() ScreenGui:Destroy() end)
    end,
}
end)()
_G._VioletteccBypassUIRuntime = _G._VioletteccBypassUI
end)

-- Settings launchers (top of Settings): press to open a tool window, press again to close.
do
    local function addLauncher(order, label, uiGlobal)
        local row = makeRowBase(pSettings, order)
        nameWithUnderline(row, label)

        local chip = Instance.new("Frame", row)
        chip.Size = UDim2.new(0, getMobileOptimized(58, 52), 0, getMobileOptimized(22, 20))
        chip.Position = UDim2.new(1, -(getMobileOptimized(58, 52) + 12), 0.5, -getMobileOptimized(11, 10))
        chip.BackgroundColor3 = ACC
        chip.BackgroundTransparency = 0.65
        chip.BorderSizePixel = 0
        chip.ZIndex = 6
        Instance.new("UICorner", chip).CornerRadius = UDim.new(0, 8)
        local chipLbl = Instance.new("TextLabel", chip)
        chipLbl.Size = UDim2.new(1, 0, 1, 0)
        chipLbl.BackgroundTransparency = 1
        chipLbl.Text = "OPEN"
        chipLbl.TextColor3 = WHITE
        chipLbl.Font = Enum.Font.GothamBold
        chipLbl.TextSize = getMobileOptimized(11, 10)
        chipLbl.ZIndex = 7

        local hit = Instance.new("TextButton", row)
        hit.Size = UDim2.new(1, 0, 1, 0)
        hit.BackgroundTransparency = 1
        hit.Text = ""
        hit.AutoButtonColor = false
        hit.ZIndex = 8
        addPressPop(row, hit)

        local function paint(isOpen)
            chipLbl.Text = isOpen and "CLOSE" or "OPEN"
            chipLbl.TextColor3 = isOpen and Color3.fromRGB(0, 0, 0) or WHITE
            TweenService:Create(chip, TweenInfo.new(0.15), {BackgroundTransparency = isOpen and 0 or 0.65}):Play()
        end
        hit.Activated:Connect(function()
            local ui = _G[uiGlobal]
            if not ui then return end
            paint(ui.Toggle())
        end)
    end

    -- negative orders keep these above every other Settings row, in this order
    addLauncher(-4, "Ping Lagger", "_VioletteccPingLaggerUI")
    addLauncher(-3, "Anti Bat", "_VioletteccAntiBatUI")
    addLauncher(-1, "Violette Bypass", "_VioletteccBypassUI")
end

