local function ResetProgressBar()
    pctMiniLbl.Text = "0%"
    if sbFillTween then pcall(function() sbFillTween:Cancel() end); sbFillTween = nil end
    if sbResetTween then pcall(function() sbResetTween:Cancel() end) end
