                    KW.wasLow = false
                    return
                end
            end
            local low = hum.WalkSpeed < 25
            if not KW.enabled then
                KW.wasLow = low
                return
            end
            if low ~= KW.wasLow then
                KW.wasLow = low
                if low then showWarning() end
            end
        end))

