            goUntil  = 0
        end
    end))

    _G._RaVeRagdollTimer = {
        setTimes = function(hit, medusa)
            if type(hit)    == "number" then HIT_TIME    = hit end
            if type(medusa) == "number" then MEDUSA_TIME = medusa end
        end,
