            _G._VioletteccRagdollCDRuntime = nil
        end,
    }
end)()


;(function()

    local SoundService = game:GetService("SoundService")
    local TweenService = game:GetService("TweenService")

    _G._VioletteccIntroSongOrder = {
        "Off",
        "Song 1",
    }

    _G._VioletteccIntroSongs = {
        ["Song 1"] = { url = "https://files.catbox.moe/fjtzoq.mp3", file = "VioletteIntroSong_fjtzoq.mp3" },
    }

    local INTRO_VOLUME = 0.65
    local MAX_PLAY     = 10

    if not _G._VioletteccIntroSongs[_G._VioletteccIntroSong] and _G._VioletteccIntroSong ~= "Off" then
        _G._VioletteccIntroSong = "Song 1"
    end
    _G._VioletteccIntroSongCache = _G._VioletteccIntroSongCache or {}
    _G._VioletteccIntroSongToken = _G._VioletteccIntroSongToken or 0

    _G._VioletteccStopIntroSong = function()
        _G._VioletteccIntroSongToken = (_G._VioletteccIntroSongToken or 0) + 1
        local snd = _G._VioletteccIntroSound
        _G._VioletteccIntroSound = nil
        if snd then
            pcall(function() snd:Stop() end)
            pcall(function() snd:Destroy() end)
        end
    end

    _G._VioletteccFadeIntroSong = function(dur)
        dur = tonumber(dur) or 0.42
        local snd = _G._VioletteccIntroSound
        _G._VioletteccIntroSongToken = (_G._VioletteccIntroSongToken or 0) + 1
        _G._VioletteccIntroSound = nil
        if not snd then return end
        pcall(function()
            TweenService:Create(snd, TweenInfo.new(dur, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Volume = 0}):Play()
        end)
        task.delay(dur + 0.05, function()
            pcall(function() snd:Stop() end)
            pcall(function() snd:Destroy() end)
        end)
    end

    _G._VioletteccGetIntroSongAsset = function(name)
        local entry = _G._VioletteccIntroSongs[name]
        if not entry then return nil end
        if _G._VioletteccIntroSongCache[name] then return _G._VioletteccIntroSongCache[name] end

        local asset = getcustomasset or getsynasset
        if type(asset) ~= "function" or type(writefile) ~= "function" then return nil end

        local onDisk = false
        pcall(function()
            onDisk = type(isfile) == "function" and isfile(entry.file) and true or false
        end)
        if not onDisk then
            local ok, body = pcall(function() return game:HttpGet(entry.url) end)
            if not ok or type(body) ~= "string" or #body == 0 then return nil end
            if not pcall(writefile, entry.file, body) then return nil end
        end

        local ok, id = pcall(asset, entry.file)
        if not ok or not id then return nil end
        _G._VioletteccIntroSongCache[name] = id
        return id
    end

    _G._VioletteccPlayIntroSong = function(name, preview)
        _G._VioletteccStopIntroSong()
        if name == nil then name = _G._VioletteccIntroSong end
        if name == "Off" then _G._VioletteccIntroSong = "Off"; return end
        if not _G._VioletteccIntroSongs[name] then return end
        _G._VioletteccIntroSong = name

        local token = _G._VioletteccIntroSongToken
        task.spawn(function()
            local id = _G._VioletteccGetIntroSongAsset(name)
            if token ~= _G._VioletteccIntroSongToken or not id then return end
            local snd = Instance.new("Sound")
            snd.Name    = preview and "VioletteIntroPreview" or "VioletteIntroMusic"
            snd.SoundId = id
            snd.Volume  = INTRO_VOLUME
            snd.Looped  = false
            snd.Parent  = SoundService
            _G._VioletteccIntroSound = snd
            pcall(function() snd:Play() end)
            task.delay(MAX_PLAY - 1, function()
                if token == _G._VioletteccIntroSongToken then _G._VioletteccFadeIntroSong(1) end
            end)
        end)
    end

    _G._RaVeIntroSong         = _G._VioletteccIntroSong
    _G._RaVeIntroSongOrder    = _G._VioletteccIntroSongOrder
    _G._RaVeIntroSongs        = _G._VioletteccIntroSongs
    _G._RaVePlayIntroSong     = _G._VioletteccPlayIntroSong
    _G._RaVeStopIntroSong     = _G._VioletteccStopIntroSong
    _G._RaVeGetIntroSongAsset = _G._VioletteccGetIntroSongAsset
end)()


