    local function dressPreview(rig, skin)
        rig.PrimaryPart = rig:FindFirstChild("HumanoidRootPart") or rig.PrimaryPart
        for _, object in ipairs(rig:GetDescendants()) do
            if object:IsA("BasePart") then
                object.CanCollide = false
                object.CastShadow = false
            elseif object:IsA("Script") or object:IsA("LocalScript") then
                object:Destroy()
            end
        end
        if skin.headless ~= false then
            local rigHead = rig:FindFirstChild("Head")
            if rigHead then
                rigHead.Transparency = 1
                for _, object in ipairs(rigHead:GetChildren()) do
                    if object:IsA("Decal") or object:IsA("Texture") then object.Transparency = 1 end
                end
            end
        end
        local mode = skin.korblox or "Off"
        for _, entry in ipairs({{"Left", "Left Leg"}, {"Right", "Right Leg"}}) do
            if mode == "Both" or mode == entry[1] then
                local config = _G._RaVeKorbloxAssets and _G._RaVeKorbloxAssets[entry[2]]
                local target = config and rig:FindFirstChild(config.targetBodyPart)
                if target then
                    for _, partName in ipairs(config.partsToHide) do
                        local limb = rig:FindFirstChild(partName)
                        if limb and limb:IsA("BasePart") then limb.Transparency = 1 end
                    end
                    local ok, objects = pcall(function() return game:GetObjects(config.id) end)
                    local source = ok and objects and objects[1]
                    local mesh = source and (source:IsA("BasePart") and source
                        or source:FindFirstChildWhichIsA("BasePart", true))
                    if mesh then
                        mesh.CanCollide = false
                        mesh.CastShadow = false
                        mesh.CFrame = target.CFrame * (config.offset or CFrame.new())
                        local weld = Instance.new("WeldConstraint")
                        weld.Part0, weld.Part1, weld.Parent = target, mesh, mesh
                        mesh.Parent = rig
                    end
                    if source and source ~= mesh and source.Parent ~= rig then
                        pcall(function() source:Destroy() end)
                    end
                end
            end
        end
    end

    local function seatStrays(rig)
        local root = rig:FindFirstChild("HumanoidRootPart")
        if not root then return end
        for _, accessory in ipairs(rig:GetChildren()) do
            if accessory:IsA("Accessory") then
                pcall(function()
                    local handle = accessory:FindFirstChild("Handle")
                    if not (handle and handle:IsA("BasePart")) then return end
                    if (handle.Position - root.Position).Magnitude <= 8 then return end

                    local handleAttachment = handle:FindFirstChildWhichIsA("Attachment")
                    local bodyAttachment
                    if handleAttachment then
                        for _, object in ipairs(rig:GetDescendants()) do
                            if object:IsA("Attachment") and object.Name == handleAttachment.Name
                                and not object:IsDescendantOf(accessory) then
                                bodyAttachment = object
                                break
                            end
                        end
                    end
                    local bodyPart = bodyAttachment and bodyAttachment.Parent
                    if bodyPart and bodyPart:IsA("BasePart") then
                        handle.CFrame = bodyPart.CFrame * bodyAttachment.CFrame
                            * handleAttachment.CFrame:Inverse()
                    else
                        local rigHead = rig:FindFirstChild("Head")
                        if rigHead then handle.CFrame = rigHead.CFrame end
                    end
                end)
            end
        end
    end

    local function loadCard(setName, card)
        task.spawn(function()
            local description = _G._KawatanBuildSetDescription
                and _G._KawatanBuildSetDescription(setName)
            if not description then card.loading.Text = "N/A" return end
            local rig
            local ok = pcall(function()
                rig = Players:CreateHumanoidModelFromDescriptionAsync(description, Enum.HumanoidRigType.R15)
            end)
            if not ok or not rig then
                pcall(function()
                    rig = Players:CreateHumanoidModelFromDescription(description, Enum.HumanoidRigType.R15)
                end)
            end
            pcall(function() description:Destroy() end)
            if not rig or not (rig:FindFirstChild("UpperTorso") or rig:FindFirstChild("Torso")) then
                if rig then pcall(function() rig:Destroy() end) end
                card.loading.Text = "N/A"
                return
            end

            pcall(dressPreview, rig, _G._KawatanSkinSets[setName])
            rig.Parent = card.world

            task.wait()
            pcall(seatStrays, rig)
            for _, object in ipairs(rig:GetDescendants()) do
                if object:IsA("BasePart") then object.Anchored = true end
            end
            pcall(function() rig:PivotTo(CFrame.new()) end)
            card.shot.rig = rig
            card.loading.Visible = false
        end)
    end

    local function selectSet(name)
        _G._KawatanSkinColor = name
        if _G._KawatanOnSetPicked then
            pcall(_G._KawatanOnSetPicked, name)
        end
        if refreshCards then refreshCards() end
    end

    for index, setName in ipairs(_G._KawatanSkinSetOrder or {}) do
        local card = new("TextButton", {
            Parent = scrolling, Name = setName .. "Preview", LayoutOrder = index,
            BackgroundColor3 = CAT_CARD, BackgroundTransparency = 0,
            BorderSizePixel = 0, Text = "", AutoButtonColor = false, ZIndex = 203,
        }, {corner(10)})
        local cardStroke = stroke(CAT_EDGE, 1, 0)
        cardStroke.Parent = card

        local viewport = new("ViewportFrame", {
            Parent = card, Name = "AvatarPreview",
            BackgroundColor3 = CAT_DARK, BackgroundTransparency = 0,
            BorderSizePixel = 0, Position = UDim2.fromOffset(7, 7),
            Size = UDim2.new(1, -14, 1, -34),
            Ambient = Color3.fromRGB(255, 255, 255), LightColor = Color3.fromRGB(255, 255, 255),
            LightDirection = Vector3.new(-0.25, -0.5, -0.83), ZIndex = 204,
        }, {corner(8)})

        local world = new("WorldModel", {Parent = viewport})
        local camera = new("Camera", {Parent = viewport, FieldOfView = 42,
            CFrame = CFrame.lookAt(Vector3.new(0, CAM_HEIGHT, CAM_DIST),
                Vector3.new(0, CAM_HEIGHT, 0))})
        viewport.CurrentCamera = camera

        local loading = new("TextLabel", {
            Parent = viewport, Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1,
            Text = "LOADING", Font = Enum.Font.GothamBold, TextSize = 9,
            TextColor3 = CAT_DIM, ZIndex = 205,
        })

        local label = new("TextLabel", {
            Parent = card, Position = UDim2.new(0, 8, 1, -24),
            Size = UDim2.new(1, -16, 0, 19), BackgroundTransparency = 1, Text = ((_G._KawatanSkinSets or {})[setName] or {}).displayName or tostring(setName):gsub("_", " "),
            Font = Enum.Font.GothamBlack, TextSize = 10,
            TextColor3 = CAT_DIM,
            TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 204,
        })

        local shot = {camera = camera, rig = nil, phase = index * 0.47,
            distance = CAM_DIST, current = CAM_DIST, target = CAM_DIST}
        shots[#shots + 1] = shot

        card.Activated:Connect(function() selectSet(setName) end)
        card.MouseEnter:Connect(function()
            shot.target = shot.distance * HOVER_ZOOM
            if _G._KawatanSkinColor ~= setName then
                tw(cardStroke, Q, {Color = CAT_EDGE_H, Transparency = 0})
                tw(label, Q, {TextColor3 = CAT_TEXT})
            end
        end)
        card.MouseLeave:Connect(function()
            shot.target = shot.distance
            if refreshCards then refreshCards() end
        end)

        cards[setName] = {card = card, stroke = cardStroke, viewport = viewport,
            world = world, camera = camera, label = label, loading = loading,
            shot = shot}
    end

    refreshCards = function()
        local live = accent()
        panelEdge.Color = live
        subtitle.TextColor3 = live
        for setName, entry in pairs(cards) do
            local on = setName == _G._KawatanSkinColor
            tw(entry.stroke, Q, {
                Color = on and live or CAT_EDGE,
                Thickness = on and 2 or 1, Transparency = 0,
            })
            tw(entry.label, Q, {TextColor3 = on and CAT_TEXT or CAT_DIM})
        end
    end
    refreshCards()
    _G._KawatanRefreshGalleryCards = refreshCards

    local elapsed = 0
    hubConnect(RunService.RenderStepped, LPH_NO_VIRTUALIZE(function(dt)
        if not catalogOpen then return end
        elapsed = elapsed + dt
        local ease = math.min(dt * DOLLY_RESPONSE, 1)
        for _, shot in ipairs(shots) do
            if shot.rig and shot.rig.Parent then
                local breath = math.cos(elapsed * 3 + shot.phase) * 0.035
                pcall(function()
                    shot.rig:PivotTo(CFrame.new(0, breath, 0)
                        * CFrame.Angles(0, math.pi + elapsed * SPIN_SPEED + shot.phase, 0))
                end)
            end
            if shot.camera.Parent then
                shot.current = shot.current + (shot.target - shot.current) * ease
                shot.camera.CFrame = CFrame.lookAt(
                    Vector3.new(0, CAM_HEIGHT, shot.current), Vector3.new(0, CAM_HEIGHT, 0))
            end
        end
    end))

    local function closeCatalog()
        catalogOpen = false
        tw(backdrop, Q, {BackgroundTransparency = 1})
        tw(panelScale, TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
            {Scale = 0.9})
        task.delay(0.16, function()
            if not catalogOpen then backdrop.Visible = false end
        end)
    end

    _G._KawatanOpenSkinGallery = function()
        catalogOpen = true
        refreshCards()
        for _, shot in ipairs(shots) do shot.target = shot.distance end
        backdrop.Visible = true
        backdrop.BackgroundTransparency = 1
        panelScale.Scale = 0.9
        tw(backdrop, TweenInfo.new(0.2), {BackgroundTransparency = 0.42})
        tw(panelScale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
            {Scale = 1})
        if built then return end
        built = true
        task.spawn(function()
            for _, setName in ipairs(_G._KawatanSkinSetOrder or {}) do
                local entry = cards[setName]
                if entry then loadCard(setName, entry) end
                task.wait(0.12)
            end
        end)
    end
    _G._KawatanCloseSkinGallery = closeCatalog

    closeBtn.Activated:Connect(closeCatalog)
    backdrop.MouseButton1Click:Connect(function()
        if panelDragging or (os.clock() - panelDragEndedAt) < 0.25 then return end
        closeCatalog()
    end)

    do
        local startInput, startPosition, dragInput
        head.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1
                and input.UserInputType ~= Enum.UserInputType.Touch then return end
            panelDragging, startInput, startPosition, dragInput =
                true, input.Position, panel.Position, input
        end)
        head.InputChanged:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement
                or input.UserInputType == Enum.UserInputType.Touch then
                dragInput = input
            end
        end)
        hubConnect(UIS.InputChanged, function(input)
            if not panelDragging then return end
            if input ~= dragInput and input.UserInputType ~= Enum.UserInputType.MouseMovement then return end
            local delta = input.Position - startInput
            panel.Position = UDim2.new(startPosition.X.Scale, startPosition.X.Offset + delta.X,
                startPosition.Y.Scale, startPosition.Y.Offset + delta.Y)
        end)
        hubConnect(UIS.InputEnded, function(input)
            if not panelDragging then return end
            if input == dragInput
                or input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                panelDragging, dragInput = false, nil
                panelDragEndedAt = os.clock()
            end
        end)
    end
end)()

    _G._VioletteccSkinGalleryRuntime = {
        Destroy = function()
            for _, c in ipairs(_conns) do pcall(function() c:Disconnect() end) end
            _conns = {}
            _G._VioletteccSkinGalleryRuntime = nil
        end,
    }
end)()

end)
if not __VL_ok then error('[Fsociety] Violette backend failed: ' .. tostring(__VL_err)) end

--[[
	Fsociety Duels  -  interface only
	Plain black, narrow and tall. Tabs sit along the bottom as pills.

	Hook your own code in:
		_G.FsocietyDuels.On("Normal Speed", function(v) ... end)
		_G.FsocietyDuels.Get("Auto Steal")
		_G.FsocietyDuels.Set("Theme", "Red")
]]

local Players          = game:GetService("Players")
local TweenService     = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")
local RunService       = game:GetService("RunService")
local HttpService      = game:GetService("HttpService")
local ContentProvider  = game:GetService("ContentProvider")

local player    = Players.LocalPlayer
local playerGui = player:WaitForChild("PlayerGui")

local old = playerGui:FindFirstChild("FsocietyDuels")
if old then old:Destroy() end

--------------------------------------------------------------------------
-- Config
--------------------------------------------------------------------------
local FILE = "fsocietyduels.json"
local saved = {}
pcall(function()
	if isfile and isfile(FILE) then saved = HttpService:JSONDecode(readfile(FILE)) end
end)
local values, defaults, refreshers, listeners = {}, {}, {}, {}

local function writeConfig()
	pcall(function()
		if writefile then writefile(FILE, HttpService:JSONEncode(values)) end
	end)
end
local function emit(name, v)
	for _, fn in ipairs(listeners[name] or {}) do task.spawn(fn, v) end
end
local function setValue(name, v, silent)
	values[name] = v
	if refreshers[name] then refreshers[name]() end
	if not silent then emit(name, v) end
	if values["Auto save"] ~= false then writeConfig() end
end
local function register(name, default)
	defaults[name] = default
	local v = saved[name]
	if v == nil or type(v) ~= type(default) then v = default end
	values[name] = v
end

--------------------------------------------------------------------------
-- Look
--------------------------------------------------------------------------
local C = {
	Bg     = Color3.fromRGB(0, 0, 0),
	Raise  = Color3.fromRGB(10, 10, 10),
	Line   = Color3.fromRGB(28, 28, 28),
	Dim    = Color3.fromRGB(85, 85, 85),
	Sub    = Color3.fromRGB(140, 140, 140),
	Text   = Color3.fromRGB(232, 232, 232),
	White  = Color3.fromRGB(255, 255, 255),
}
local ACCENTS = {
	White = Color3.fromRGB(255, 255, 255),
	Red   = Color3.fromRGB(230, 40, 46),
	Green = Color3.fromRGB(60, 230, 110),
	Amber = Color3.fromRGB(255, 176, 0),
}
local ACCENT_ORDER = { "White", "Red", "Green", "Amber" }
register("Accent", "White")
local Accent = ACCENTS[values["Accent"]] or ACCENTS.White
local accentHooks = {}
local function onAccent(fn) table.insert(accentHooks, fn) fn(true) end

local MONO, MONO_B = Enum.Font.GothamMedium, Enum.Font.GothamBold

local function new(class, props, children)
	local o = Instance.new(class)
	for k, v in pairs(props or {}) do
		if k ~= "Parent" then o[k] = v end
	end
	for _, c in ipairs(children or {}) do c.Parent = o end
	if props and props.Parent then o.Parent = props.Parent end
	return o
end
local function tween(o, t, goal, style, dir)
	local tw = TweenService:Create(o, TweenInfo.new(t, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out), goal)
	tw:Play()
	return tw
end
local function corner(r) return new("UICorner", { CornerRadius = UDim.new(0, r) }) end
local function stroke(col, tr, th)
	return new("UIStroke", { Color = col, Transparency = tr or 0, Thickness = th or 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border })
end
local function text(props)
	props.BackgroundTransparency = 1
	props.Font = props.Font or MONO
	props.TextSize = props.TextSize or 13
	props.TextColor3 = props.TextColor3 or C.Text
	props.TextXAlignment = props.TextXAlignment or Enum.TextXAlignment.Left
	return new("TextLabel", props)
end

--------------------------------------------------------------------------
-- Sound: short, quiet, preloaded and pooled so nothing lags
--------------------------------------------------------------------------
register("Sounds", true)
register("Volume", 60)
local SFX = {
	Click  = { "rbxasset://sounds/clickfast.wav", 0.5 },
	Toggle = { "rbxasset://sounds/electronicpingshort.wav", 0.25 },
	Tick   = { "rbxasset://sounds/clickfast.wav", 0.25 },
}
local pools = {}
local sfxFolder = new("Folder", { Name = "FsocietySFX", Parent = playerGui })
for name, s in pairs(SFX) do
	pools[name] = { i = 0 }
	for k = 1, 4 do
		pools[name][k] = new("Sound", { SoundId = s[1], Volume = s[2], Parent = sfxFolder })
	end
end
task.spawn(function() pcall(function() ContentProvider:PreloadAsync(sfxFolder:GetChildren()) end) end)
local function play(name, pitch)
	if not values["Sounds"] then return end
	local p = pools[name]
	if not p then return end
	p.i = p.i % 4 + 1
	local snd = p[p.i]
	snd.Volume = SFX[name][2] * (values["Volume"] / 100)
	snd.PlaybackSpeed = pitch or 1
	snd.TimePosition = 0
	snd:Play()
end

--------------------------------------------------------------------------
-- Window
--------------------------------------------------------------------------
local W, H = 290, 440 -- narrow and tall
local gui = new("ScreenGui", {
	Name = "FsocietyDuels",
	ResetOnSpawn = false,
	IgnoreGuiInset = true,
	ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
	DisplayOrder = 100,
	Parent = playerGui,
})
gui.Destroying:Connect(function() sfxFolder:Destroy() end)

register("UI Scale", 100)
local root = new("Frame", {
	AnchorPoint = Vector2.new(0.5, 0.5),
	Position = UDim2.fromScale(0.5, 0.5),
	Size = UDim2.fromOffset(W, H),
	BackgroundColor3 = C.Bg,
	BorderSizePixel = 0,
	Parent = gui,
}, { corner(6) })
local rootStroke = stroke(C.Line)
rootStroke.Parent = root
local rootScale = new("UIScale", { Scale = values["UI Scale"] / 100, Parent = root })

-- title
local prompt = text({
	Text = "", RichText = true, Font = Enum.Font.GothamBlack, TextSize = 15,
	Position = UDim2.fromOffset(16, 0), Size = UDim2.new(1, -80, 0, 40), Parent = root,
})
onAccent(function()
	prompt.Text = string.format('FSOCIETY <font color="#%s">DUELS</font>', Accent:ToHex())
end)

local closeBtn = new("TextButton", {
	AnchorPoint = Vector2.new(1, 0),
	Position = UDim2.new(1, -10, 0, 10),
	Size = UDim2.fromOffset(22, 20),
	BackgroundTransparency = 1,
	Font = MONO_B, TextSize = 13, TextColor3 = C.Dim, Text = "x",
	Parent = root,
})
local minBtn = new("TextButton", {
	AnchorPoint = Vector2.new(1, 0),
	Position = UDim2.new(1, -34, 0, 10),
	Size = UDim2.fromOffset(22, 20),
	BackgroundTransparency = 1,
	Font = MONO_B, TextSize = 13, TextColor3 = C.Dim, Text = "_",
	Parent = root,
})
for _, b in ipairs({ closeBtn, minBtn }) do
	b.MouseEnter:Connect(function() tween(b, 0.12, { TextColor3 = C.White }) end)
	b.MouseLeave:Connect(function() tween(b, 0.2, { TextColor3 = C.Dim }) end)
end

-- tab strip under the prompt
local TAB_Y = H - 38 -- tabs sit along the bottom
-- the dock: a rounded bar the tabs sit in
local dock = new("Frame", {
	Position = UDim2.new(0, 7, 0, TAB_Y - 3),
	Size = UDim2.new(1, -14, 0, 36),
	BackgroundColor3 = C.Raise,
	BorderSizePixel = 0,
	ZIndex = 1,
	Parent = root,
}, { corner(18) })
stroke(C.Line).Parent = dock
local tabStrip = new("Frame", {
	Position = UDim2.new(0, 10, 0, TAB_Y),
	Size = UDim2.new(1, -20, 0, 30),
	BackgroundTransparency = 1,
	BorderSizePixel = 0,
	ZIndex = 3,
	Parent = root,
}, {
	new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, SortOrder = Enum.SortOrder.LayoutOrder, VerticalAlignment = Enum.VerticalAlignment.Center }),
})
for _, y in ipairs({ 40 }) do
	new("Frame", { Position = UDim2.fromOffset(0, y), Size = UDim2.new(1, 0, 0, 1), BackgroundColor3 = C.Line, BorderSizePixel = 0, ZIndex = 2, Parent = root })
end
local underline = new("Frame", { -- pill behind the active tab
	Position = UDim2.fromOffset(0, TAB_Y + 3),
	Size = UDim2.fromOffset(0, 24),
	BackgroundColor3 = Accent,
	BorderSizePixel = 0,
	ZIndex = 2,
	Parent = root,
}, { corner(12) })
local pillGlow = stroke(Accent, 0.6, 2)
pillGlow.Parent = underline
onAccent(function(i) tween(pillGlow, i and 0 or 0.3, { Color = Accent }) end)
onAccent(function(i) tween(underline, i and 0 or 0.3, { BackgroundColor3 = Accent }) end)

local function setStatus() end -- no status text

-- pages live between the tab strip and the status line
local content = new("Frame", {
	Position = UDim2.fromOffset(0, 41),
	Size = UDim2.new(1, 0, 0, TAB_Y - 4 - 41),
	BackgroundTransparency = 1,
	ClipsDescendants = true,
	Parent = root,
})

-- drag by the prompt line (mouse and touch)
do
	local handle = new("TextButton", { Size = UDim2.new(1, -60, 0, 40), BackgroundTransparency = 1, Text = "", ZIndex = 5, Parent = root })
	local dragging, startPos, startInput
	handle.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragging, startPos, startInput = true, root.Position, input.Position
		end
	end)
	UserInputService.InputChanged:Connect(function(input)
		if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			local d = input.Position - startInput
			root.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
		end
	end)
	UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = false end
	end)
end

--------------------------------------------------------------------------
-- Tabs and pages
--------------------------------------------------------------------------
local tabs, currentTab, building = {}, nil, nil
local order = 0

local function selectTab(tab, instant)
	if currentTab == tab then return end
	currentTab = tab
	for _, t in ipairs(tabs) do
		local on = t == tab
		tween(t.Label, instant and 0 or 0.2, { TextColor3 = on and C.Bg or C.Dim })
		if not on then t.Page.Visible = false end
	end
	local x = tab.Button.AbsolutePosition.X - root.AbsolutePosition.X
	x = x / math.max(rootScale.Scale, 0.01)
	tween(underline, instant and 0 or 0.3, { Position = UDim2.fromOffset(x + 3, TAB_Y + 3), Size = UDim2.fromOffset(tab.Button.AbsoluteSize.X / math.max(rootScale.Scale, 0.01) - 6, 24) }, Enum.EasingStyle.Back)
	-- the page "types" in: rows appear one after another from the left
	tab.Page.Visible = true
	tab.Page.CanvasPosition = Vector2.zero
	for k, r in ipairs(tab.Rows) do
		if instant then
			r.Position = UDim2.fromOffset(0, 0)
		else
			r.Position = UDim2.fromOffset(-12, 0)
			task.delay(k * 0.02, function() tween(r, 0.25, { Position = UDim2.fromOffset(0, 0) }) end)
		end
	end
	if not instant then
		play("Click", 1.15)
		setStatus(tab.Name)
	end
end

local function addTab(name)
	local btn = new("TextButton", {
		Size = UDim2.new(0.25, 0, 1, 0), -- four equal tabs
		BackgroundTransparency = 1,
		Text = "",
		LayoutOrder = #tabs + 1,
		ZIndex = 3,
		Parent = tabStrip,
	}, { new("UIScale", {}) })
	local lbl = text({
		Text = name,
		Font = MONO_B, TextSize = 11, TextColor3 = C.Dim,
		TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 4,
		Size = UDim2.fromScale(1, 1), Parent = btn,
	})
	local page = new("ScrollingFrame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		ScrollBarThickness = 2,
		ScrollBarImageColor3 = C.Dim,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		Visible = false,
		Parent = content,
	}, {
		new("UIPadding", { PaddingTop = UDim.new(0, 8), PaddingBottom = UDim.new(0, 10), PaddingLeft = UDim.new(0, 14), PaddingRight = UDim.new(0, 14) }),
		new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }),
	})
	local tab = { Name = name, Button = btn, Label = lbl, Page = page, Rows = {} }
	btn.MouseEnter:Connect(function() if currentTab ~= tab then tween(lbl, 0.12, { TextColor3 = C.Sub }) end end)
	btn.MouseLeave:Connect(function() if currentTab ~= tab then tween(lbl, 0.2, { TextColor3 = C.Dim }) end end)
	local press = btn:FindFirstChildOfClass("UIScale")
	btn.MouseButton1Down:Connect(function() tween(press, 0.08, { Scale = 0.92 }) end)
	btn.MouseButton1Up:Connect(function() tween(press, 0.25, { Scale = 1 }, Enum.EasingStyle.Back) end)
	btn.MouseLeave:Connect(function() tween(press, 0.2, { Scale = 1 }) end)
	btn.MouseButton1Click:Connect(function() selectTab(tab) end)
	table.insert(tabs, tab)
	building = tab
end

-- each row is a holder in the list with an inner frame that can slide
local function row(height)
	order += 1
	local holder = new("Frame", { Size = UDim2.new(1, 0, 0, height), BackgroundTransparency = 1, LayoutOrder = order, Parent = building.Page })
	local inner = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Parent = holder })
	table.insert(building.Rows, inner)
	return inner
end

local function Section(name)
	local r = row(#building.Rows == 0 and 24 or 36)
	text({
		Text = string.upper(name),
		Font = MONO_B, TextSize = 11, TextColor3 = C.Dim,
		Position = UDim2.new(0, 0, 1, -20), Size = UDim2.new(1, 0, 0, 16), Parent = r,
	})
end

-- a setting line: "name ..........  value"
local function Line(name, height)
	local r = row(height or 30)
	local hover = new("Frame", { Size = UDim2.new(1, 12, 1, -2), Position = UDim2.fromOffset(-6, 1), BackgroundColor3 = C.White, BackgroundTransparency = 1, BorderSizePixel = 0, Parent = r }, { corner(3) })
	local marker = text({ Text = "", Font = MONO_B, TextSize = 13, TextColor3 = Accent, TextTransparency = 1, Position = UDim2.fromOffset(-2, 0), Size = UDim2.new(0, 10, 0, 30), Parent = r })
	onAccent(function() marker.TextColor3 = Accent end)
	local lbl = text({ Text = name, TextSize = 13, Position = UDim2.fromOffset(0, 0), Size = UDim2.new(0.6, 0, 0, 30), Parent = r })
	local hit = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", ZIndex = 2, Parent = r })
	local function hl(on)
		tween(hover, 0.15, { BackgroundTransparency = on and 0.96 or 1 })
		tween(marker, 0.15, { TextTransparency = on and 0 or 1 })
		tween(lbl, 0.15, { Position = UDim2.fromOffset(on and 4 or 0, 0), TextColor3 = on and C.White or C.Text })
	end
	hit.MouseEnter:Connect(function() hl(true) end)
	hit.MouseLeave:Connect(function() hl(false) end)
	return r, hit
end

local function valueLabel(parent, width)
	return text({
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 0, 0, 0),
		Size = UDim2.new(0, width or 120, 0, 30),
		TextXAlignment = Enum.TextXAlignment.Right,
		Font = MONO_B, TextSize = 13, ZIndex = 3,
		Parent = parent,
	})
end

local function Toggle(name, default, onChanged)
	register(name, default)
	local r, hit = Line(name)
	local sw = new("Frame", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0, 15), Size = UDim2.fromOffset(34, 18), BackgroundColor3 = C.Line, BorderSizePixel = 0, ZIndex = 3, Parent = r }, { corner(9) })
	local knob = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 3, 0.5, 0), Size = UDim2.fromOffset(12, 12), BackgroundColor3 = C.Sub, BorderSizePixel = 0, ZIndex = 4, Parent = sw }, { corner(6) })
	local function paint(instant)
		local on = values[name]
		local t = instant and 0 or 0.2
		tween(sw, t, { BackgroundColor3 = on and Accent or C.Line })
		tween(knob, t, { Position = on and UDim2.new(1, -15, 0.5, 0) or UDim2.new(0, 3, 0.5, 0), BackgroundColor3 = on and C.Bg or C.Sub }, Enum.EasingStyle.Back)
	end
	refreshers[name] = function() paint(false) end
	onAccent(paint)
	hit.MouseButton1Click:Connect(function()
		setValue(name, not values[name])
		play("Toggle", values[name] and 1.2 or 0.9)
		setStatus(string.format("%s: %s", name, values[name] and "On" or "Off"))
		if onChanged then onChanged(values[name]) end
	end)
end

local function Number(name, default, min, max, step)
	step = step or 1
	register(name, default)
	local r, hit = Line(name, 42)
	local box = new("TextBox", {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 0, 0, 0),
		Size = UDim2.fromOffset(70, 30),
		BackgroundTransparency = 1,
		ClearTextOnFocus = false,
		TextXAlignment = Enum.TextXAlignment.Right,
		Font = MONO_B, TextSize = 13, TextColor3 = C.White,
		Text = tostring(values[name]),
		ZIndex = 4,
		Parent = r,
	})
	-- slider: a dotted track and a solid fill
	local track = new("Frame", { Position = UDim2.new(0, 0, 0, 32), Size = UDim2.new(1, 0, 0, 2), BackgroundColor3 = C.Line, BorderSizePixel = 0, ZIndex = 3, Parent = r })
	local fill = new("Frame", { Size = UDim2.fromScale(0, 1), BackgroundColor3 = Accent, BorderSizePixel = 0, ZIndex = 3, Parent = track })
	local head = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0, 0.5), Size = UDim2.fromOffset(4, 10), BackgroundColor3 = C.White, BorderSizePixel = 0, ZIndex = 4, Parent = track })
	onAccent(function() fill.BackgroundColor3 = Accent end)
	local dragging = false
	local function paint()
		local a = max > min and math.clamp((values[name] - min) / (max - min), 0, 1) or 0
		local t = dragging and 0.05 or 0.3
		tween(fill, t, { Size = UDim2.fromScale(a, 1) })
		tween(head, t, { Position = UDim2.fromScale(a, 0.5) })
		if not box:IsFocused() then box.Text = tostring(values[name]) end
	end
	refreshers[name] = paint
	paint()
	local function commit(n, live)
		n = math.clamp(math.floor(n / step + 0.5) * step, min, max)
		if live then
			if n == values[name] then return end
			values[name] = n
			paint()
			emit(name, n)
			play("Tick", 0.9 + (n - min) / math.max(max - min, 1) * 0.4)
		else
			setValue(name, n)
		end
	end
	box.FocusLost:Connect(function()
		local n = tonumber(box.Text)
		if n then commit(n) play("Click") setStatus(name .. ": " .. values[name]) else box.Text = tostring(values[name]) end
	end)
	hit.InputChanged:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseWheel and not box:IsFocused() then
			commit(values[name] + (input.Position.Z > 0 and step or -step))
			play("Tick")
		end
	end)
	local dragHit = new("TextButton", { Position = UDim2.new(0, 0, 0, 24), Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1, Text = "", ZIndex = 5, Parent = r })
	local function dragTo(x)
		local a = math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)
		commit(min + a * (max - min), true)
	end
	dragHit.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragging = true
			tween(head, 0.15, { Size = UDim2.fromOffset(4, 14) })
			dragTo(input.Position.X)
		end
	end)
	UserInputService.InputChanged:Connect(function(input)
		if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			dragTo(input.Position.X)
		end
	end)
	UserInputService.InputEnded:Connect(function(input)
		if dragging and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
			dragging = false
			tween(head, 0.2, { Size = UDim2.fromOffset(4, 10) })
			setValue(name, values[name])
			setStatus(name .. ": " .. values[name])
		end
	end)
end

local function Choice(name, options, default, onChanged)
	register(name, default)
	local r, hit = Line(name)
	local v = valueLabel(r, 160)
	local function paint()
		v.Text = values[name] .. "  \u{203A}"
	end
	refreshers[name] = paint
	paint()
	local function step(dir)
		local i = table.find(options, values[name]) or 1
		i = (i - 1 + dir) % #options + 1
		setValue(name, options[i])
		play("Click", dir > 0 and 1.1 or 0.95)
		v.TextColor3 = Accent
		tween(v, 0.4, { TextColor3 = C.Text })
		setStatus(name .. ": " .. options[i])
		if onChanged then onChanged(options[i]) end
	end
	hit.MouseButton1Click:Connect(function() step(1) end)
	hit.MouseButton2Click:Connect(function() step(-1) end)
end

local keyHooks = {}
local hud = {}
local listening = nil
local function Keybind(name, default)
	register(name, default)
	local r, hit = Line(name)
	local v = valueLabel(r, 90)
	local function paint()
		v.Text = values[name]
		v.TextColor3 = C.Text
	end
	refreshers[name] = paint
	paint()
	hit.MouseButton1Click:Connect(function()
		listening = name
		v.Text = "..."
		v.TextColor3 = Accent
		play("Click")
		setStatus("Press a key for " .. name)
	end)
	keyHooks[name] = paint
end

local function Button(name, onClick)
	local r, hit = Line(name)
	local v = valueLabel(r, 60)
	v.Text = "Run"
	v.TextColor3 = C.Dim
	hit.MouseEnter:Connect(function() tween(v, 0.12, { TextColor3 = Accent }) end)
	hit.MouseLeave:Connect(function() tween(v, 0.2, { TextColor3 = C.Dim }) end)
	hit.MouseButton1Click:Connect(function()
		play("Click", 1.2)
		v.Text = "Done"
		task.delay(0.6, function() v.Text = "Run" end)
		setStatus(name)
		if onClick then task.spawn(onClick) end
	end)
end

local function Credit(name, role)
	local r = Line(name)
	local v = valueLabel(r, 200)
	v.Text = role
	v.Font = MONO
	v.TextColor3 = C.Sub
end

local function setAccent(name)
	Accent = ACCENTS[name] or ACCENTS.White
	for _, fn in ipairs(accentHooks) do fn(false) end
end

