local function addViolettePage(pageName)
    local vl = _G.VL
    if not vl or not vl.rows or not vl.pageName then return end
    Section("Violette " .. pageName)
    local rows = {}
    for _, r in ipairs(vl.rows) do
        if vl.pageName[r.page] == pageName then rows[#rows + 1] = r end
    end
    table.sort(rows, function(a,b) return (a.order or 0) < (b.order or 0) end)
    for _, r in ipairs(rows) do
        local entry = r.kind == "T" and vl.T[r.key] or r.kind == "N" and vl.N[r.key] or r.kind == "C" and vl.C[r.key]
        local label = "V: " .. tostring(r.key):gsub("#(%d+)$", " (%1)")
        -- Existing rows have dedicated mappings below. Bindable/action rows require explicit handling.
        local skip = r.key == "Auto Steal" or r.key == "Infinite Jump" or r.key == "Anti Ragdoll" or r.key == "Auto Swing"
        if entry and not skip and not defaults[label] then
            if r.kind == "T" and not r.noSwitch then
                local ok, current = pcall(entry.get)
                Toggle(label, ok and current == true)
                listeners[label] = { function(v) entry.set(v == true) end }
            elseif r.kind == "N" then
                local ok, current = pcall(entry.get)
                local def = ok and tonumber(current) or tonumber(r.def) or 0
                -- Broad editor range; the backend callback enforces its own domain.
                Number(label, def, -5000, 5000, 1)
                listeners[label] = { function(v) entry.set(v) end }
            elseif r.kind == "C" and type(r.values) == "table" and #r.values > 0 then
                local opts = {}
                for _, v in ipairs(r.values) do opts[#opts+1] = tostring(v) end
                Choice(label, opts, tostring(r.init or opts[1]))
                listeners[label] = { function(v) entry.set(v) end }
            end
        end
    end
end

