-- Show / hide
--------------------------------------------------------------------------
local visible = true
local visToken = 0
local function setVisible(v)
	visible = v
	visToken += 1
	local token = visToken
	local s = values["UI Scale"] / 100
	if v then
		root.Visible = true
		rootScale.Scale = s * 0.96
		root.BackgroundTransparency = 0
		tween(rootScale, 0.25, { Scale = s })
		play("Click", 1.3)
	else
		tween(rootScale, 0.15, { Scale = s * 0.96 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		play("Click", 0.8)
		task.delay(0.15, function() if token == visToken then root.Visible = false end end)
	end
end
closeBtn.MouseButton1Click:Connect(function() setVisible(false) end)
-- minimize folds the window up to its header instead of hiding it
local minimized = false
root.ClipsDescendants = true
minBtn.MouseButton1Click:Connect(function()
	minimized = not minimized
	play("Click", minimized and 0.9 or 1.2)
	minBtn.Text = minimized and "+" or "_"
	tween(root, 0.35, { Size = UDim2.fromOffset(W, minimized and 40 or H) }, Enum.EasingStyle.Quint)
end)
listeners["UI Scale"] = { function(v) if visible then tween(rootScale, 0.2, { Scale = v / 100 }) end end }

UserInputService.InputBegan:Connect(function(input, processed)
	if listening and input.UserInputType == Enum.UserInputType.Keyboard then
		local name = listening
		listening = nil
		if input.KeyCode ~= Enum.KeyCode.Escape then setValue(name, input.KeyCode.Name) end
		if keyHooks[name] then keyHooks[name]() end
		play("Toggle", 1.1)
		setStatus(name .. ": " .. values[name])
		return
	end
	if processed then return end
	if input.KeyCode.Name == values["Menu Key"] then setVisible(not visible) end
	for name in pairs(keyHooks) do
		if name ~= "Menu Key" and input.KeyCode.Name == values[name] then emit("Pressed:" .. name, true) end
	end
end)

-- mobile: a small draggable "fs" square that opens and closes the menu
do
	local btn = new("TextButton", {
		Position = UDim2.new(0, 16, 0.5, -24),
		Size = UDim2.fromOffset(48, 48),
		BackgroundColor3 = C.Bg,
		AutoButtonColor = false,
		Font = MONO_B, TextSize = 16, TextColor3 = C.White, Text = "FS",
		Visible = values["Mobile button"],
		Parent = gui,
	}, { corner(6) })
	local bs = stroke(Accent, 0.3)
	bs.Parent = btn
	onAccent(function() bs.Color = Accent end)
	refreshers["Mobile button"] = (function(prev)
		return function() if prev then prev() end btn.Visible = values["Mobile button"] end
	end)(refreshers["Mobile button"])
	local down, moved, startPos, startInput
	btn.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			down, moved, startPos, startInput = true, false, btn.Position, input.Position
		end
	end)
	UserInputService.InputChanged:Connect(function(input)
		if down and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			local d = input.Position - startInput
			if d.Magnitude > 6 then moved = true end
			if moved then btn.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y) end
		end
	end)
	UserInputService.InputEnded:Connect(function(input)
		if down and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
			down = false
			if not moved then setVisible(not visible) end
		end
	end)
end

--------------------------------------------------------------------------
-- HUD: steal bar and mobile buttons (interface only, your code drives it)
--   _G.FsocietyDuels.SetStealProgress(0.5, "Stealing")   -- 0 to 1
--   _G.FsocietyDuels.On("Pressed:Speed Key", fn)          -- keybind / mobile key pressed
--   _G.FsocietyDuels.On("TP Down", fn)                    -- mobile action button
--------------------------------------------------------------------------
do
	local hudGui = new("ScreenGui", { Name = "FsocietyHUD", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 50, ZIndexBehavior = Enum.ZIndexBehavior.Sibling, Parent = playerGui })
	gui.Destroying:Connect(function() hudGui:Destroy() end)

	------------------------------------------------------------------
	-- steal bar, top middle
	------------------------------------------------------------------
	local bar = new("CanvasGroup", {
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, -50),
		Size = UDim2.fromOffset(260, 38),
		BackgroundColor3 = C.Bg,
		GroupTransparency = 1,
		Visible = false,
		Parent = hudGui,
	}, { corner(8) })
	local barStroke = stroke(C.Line)
	barStroke.Parent = bar
	local status = text({ Text = "STEALING", Font = Enum.Font.GothamBlack, TextSize = 11, TextColor3 = C.Text, Position = UDim2.fromOffset(12, 4), Size = UDim2.new(1, -24, 0, 16), Parent = bar })
	local pct = text({ Text = "0%", Font = Enum.Font.GothamBold, TextSize = 11, TextColor3 = C.Sub, TextXAlignment = Enum.TextXAlignment.Right, Position = UDim2.fromOffset(12, 4), Size = UDim2.new(1, -24, 0, 16), Parent = bar })
	local track = new("Frame", { Position = UDim2.new(0, 12, 0, 24), Size = UDim2.new(1, -24, 0, 6), BackgroundColor3 = C.Line, BorderSizePixel = 0, Parent = bar }, { corner(3) })
	local fill = new("Frame", { Size = UDim2.fromScale(0, 1), BackgroundColor3 = Accent, BorderSizePixel = 0, Parent = track }, { corner(3) })
	local shine = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = C.White, BackgroundTransparency = 0.6, BorderSizePixel = 0, Parent = fill }, {
		corner(3), new("UIGradient", { Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0.3), NumberSequenceKeypoint.new(1, 1) }), Offset = Vector2.new(-1, 0) }),
	})
	local shineGrad = shine:FindFirstChildOfClass("UIGradient")
	TweenService:Create(shineGrad, TweenInfo.new(1.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1), { Offset = Vector2.new(1, 0) }):Play()
	onAccent(function(i) tween(fill, i and 0 or 0.3, { BackgroundColor3 = Accent }) end)

	local shown, testing, progress = false, false, 0
	local function showBar(on)
		if on == shown then return end
		shown = on
		if on then
			bar.Visible = true
			tween(bar, 0.4, { Position = UDim2.new(0.5, 0, 0, 12), GroupTransparency = 0 }, Enum.EasingStyle.Back)
		else
			tween(bar, 0.25, { Position = UDim2.new(0.5, 0, 0, -50), GroupTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			task.delay(0.26, function() if not shown then bar.Visible = false end end)
		end
	end
	hud.setStealProgress = function(alpha, label)
		alpha = math.clamp(tonumber(alpha) or 0, 0, 1)
		progress = alpha
		tween(fill, 0.15, { Size = UDim2.fromScale(alpha, 1) }, Enum.EasingStyle.Linear)
		pct.Text = math.floor(alpha * 100 + 0.5) .. "%"
		status.Text = string.upper(label or (alpha >= 1 and "STOLEN" or "STEALING"))
		if alpha >= 1 then
			barStroke.Color = Accent
			tween(barStroke, 0.6, { Color = C.Line })
			play("Toggle", 1.3)
		end
	end
	hud.updateSteal = function()
		showBar(testing or (values["Show steal bar"] and values["Auto Steal"]))
	end
	hud.testSteal = function()
		if testing then return end
		testing = true
		hud.updateSteal()
		task.spawn(function()
			for k = 0, 20 do
				hud.setStealProgress(k / 20, k < 20 and "Stealing" or "Stolen")
				task.wait(0.1)
			end
			task.wait(1)
			testing = false
			hud.setStealProgress(0)
			hud.updateSteal()
		end)
	end
	hud.updateSteal()

	------------------------------------------------------------------
	-- mobile buttons: a draggable cluster, same layout as before
	------------------------------------------------------------------
	local CELL, GAP = 62, 8
	local MOBILE = {
		{ "AUTO\nLEFT", "Auto Left", "flag", 1, 1 }, { "LAGGER\nCARRY", "Lagger Carry Toggle", "flag", 2, 1 }, { "TP DOWN", "TP Down", "action", 3, 1 },
		{ "DROP\nBRAINROT", "Drop Brainrot", "action", 2, 2 }, { "AUTO\nRIGHT", "Auto Right", "flag", 3, 2 }, { "CARRY\nSPEED", "Speed Key", "key", 2, 3 },
		{ "BAT\nAIMBOT", "Aim Assist", "toggle", 3, 3 }, { "LAGGER\nMODE", "Lagger Key", "key", 2, 4 }, { "INSTA\nRESET", "Insta Reset", "action", 3, 4 },
	}
	local cluster = new("Frame", {
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.new(1, -20, 1, -110),
		Size = UDim2.fromOffset(3 * CELL + 2 * GAP, 4 * CELL + 3 * GAP),
		BackgroundTransparency = 1,
		Visible = values["Mobile buttons"],
		Parent = hudGui,
	})
	local clusterScale = new("UIScale", { Scale = values["Button size"] / 100, Parent = cluster })
	listeners["Button size"] = listeners["Button size"] or {}
	table.insert(listeners["Button size"], function(v) tween(clusterScale, 0.2, { Scale = v / 100 }) end)

	local painters = {}
	local dragging, moved, startPos, startInput = false, false, nil, nil
	for _, m in ipairs(MOBILE) do
		local label, name, kind, col, rowN = m[1], m[2], m[3], m[4], m[5]
		if kind == "flag" then register(name, false) end
		local b = new("TextButton", {
			Position = UDim2.fromOffset((col - 1) * (CELL + GAP), (rowN - 1) * (CELL + GAP)),
			Size = UDim2.fromOffset(CELL, CELL),
			BackgroundColor3 = C.Bg,
			BackgroundTransparency = 0.1,
			AutoButtonColor = false,
			Font = Enum.Font.GothamBlack, TextSize = 10, TextColor3 = C.Text,
			Text = label,
			Parent = cluster,
		}, { corner(10), new("UIScale", {}) })
		local bs = stroke(C.Line, 0, 1.5)
		bs.Parent = b
		local sc = b:FindFirstChildOfClass("UIScale")
		local function paint()
			local on = (kind == "flag" or kind == "toggle") and values[name]
			tween(b, 0.15, { BackgroundColor3 = on and Accent or C.Bg, TextColor3 = on and C.Bg or C.Text })
			tween(bs, 0.15, { Color = on and Accent or C.Line })
		end
		table.insert(painters, paint)
		onAccent(paint)
		if kind == "flag" or kind == "toggle" then
			local prev = refreshers[name]
			refreshers[name] = function() if prev then prev() end paint() end
		end
		b.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				dragging, moved, startPos, startInput = true, false, cluster.Position, input.Position
				tween(sc, 0.08, { Scale = 0.92 })
			end
		end)
		b.InputEnded:Connect(function(input)
			if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
			tween(sc, 0.25, { Scale = 1 }, Enum.EasingStyle.Back)
			if moved then return end
			if kind == "flag" or kind == "toggle" then
				setValue(name, not values[name])
				play("Toggle", values[name] and 1.2 or 0.9)
			elseif kind == "key" then
				emit("Pressed:" .. name, true)
				play("Click", 1.1)
				b.BackgroundColor3 = Accent
				tween(b, 0.3, { BackgroundColor3 = C.Bg })
			else
				emit(name, true)
				play("Click", 1.2)
				b.BackgroundColor3 = Accent
				tween(b, 0.3, { BackgroundColor3 = C.Bg })
			end
		end)
	end
	UserInputService.InputChanged:Connect(function(input)
		if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			local d = input.Position - startInput
			if d.Magnitude > 8 then moved = true end
			if moved then cluster.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y) end
		end
	end)
	UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = false end
	end)
	hud.setMobile = function(on)
		if on then
			cluster.Visible = true
			clusterScale.Scale = 0
			tween(clusterScale, 0.35, { Scale = values["Button size"] / 100 }, Enum.EasingStyle.Back)
		else
			tween(clusterScale, 0.2, { Scale = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			task.delay(0.21, function() if not values["Mobile buttons"] then cluster.Visible = false end end)
		end
	end
	hud.resetMobile = function()
		tween(cluster, 0.4, { Position = UDim2.new(1, -20, 1, -110) }, Enum.EasingStyle.Quint)
	end
end

--------------------------------------------------------------------------
-- Public hooks
--------------------------------------------------------------------------
_G.FsocietyDuels = {
	On = function(name, fn)
		listeners[name] = listeners[name] or {}
		table.insert(listeners[name], fn)
	end,
	Get = function(name) return values[name] end,
	SetStealProgress = function(alpha, label) if hud.setStealProgress then hud.setStealProgress(alpha, label) end end,
	Set = function(name, v) setValue(name, v) end,
}


-- Bridge existing Fsociety controls to Violette's registry and action API.
do
    local vl = _G.VL or {}
    local function listen(name, fn)
        listeners[name] = listeners[name] or {}
        table.insert(listeners[name], fn)
    end
    local function invoke(label, fn, ...)
        if type(fn) ~= "function" then warn("[Fsociety] Missing Violette handler: " .. label); return end
        local ok, err = pcall(fn, ...)
        if not ok then warn("[Fsociety] " .. label .. ": " .. tostring(err)) end
    end
    for name, global in pairs({["Normal Speed"]="NormalSpeed_Normal", ["Carry Speed"]="NormalSpeed_Carry", ["Lagger Normal"]="LaggerSpeed_Normal", ["Lagger Carry"]="LaggerSpeed_Carry"}) do
        local function apply(v)
            _G[global] = tonumber(v) or 0
            local s = _G._VioletteccSpd
            if s then invoke("speed refresh", s.Refresh) end
        end
        listen(name, apply); apply(values[name])
    end
    for uiName, key in pairs({["Auto Swing"]="Auto Swing", ["Infinite Jump"]="Infinite Jump", ["Anti Ragdoll"]="Anti Ragdoll", ["Auto Steal"]="Auto Steal"}) do
        local t = vl.T and vl.T[key]
        if t then
            local function apply(v) invoke(key, t.set, v == true) end
            listen(uiName, apply); apply(values[uiName])
        else warn("[Fsociety] Missing toggle: " .. key) end
    end
    for name, value in pairs(values) do
        if name:sub(1, 3) == "V: " then
            for _, fn in ipairs(listeners[name] or {}) do invoke(name, fn, value) end
        end
    end
    local radius = vl.N and vl.N["Radius"]
    if radius then
        local function apply(v) invoke("Steal Radius", radius.set, v) end
        listen("Steal Radius", apply); apply(values["Steal Radius"])
    else warn("[Fsociety] Missing steal radius handler") end
    local act = vl.act or {}
    listen("Aim Assist", function(v) invoke("Bat Aimbot", act.bat, v) end)
    invoke("Bat Aimbot", act.bat, values["Aim Assist"])
    for event, action in pairs({["Pressed:Speed Key"]="carry", ["Pressed:Lagger Key"]="lagger", ["TP Down"]="tpDown", ["Drop Brainrot"]="drop", ["Insta Reset"]="instaReset", ["Auto Left"]="autoLeft", ["Auto Right"]="autoRight", ["Lagger Carry Toggle"]="laggerCarry"}) do
        listen(event, function(v) invoke(action, act[action], v) end)
    end
    listen("Accent", setAccent)
    listen("Mobile buttons", function(v) if hud.setMobile then hud.setMobile(v) end end)
    listen("Show steal bar", function() if hud.updateSteal then hud.updateSteal() end end)
    listen("Auto Steal", function() if hud.updateSteal then hud.updateSteal() end end)
    _G.StealBar = {
        SetProgress = function(v) if hud.setStealProgress then hud.setStealProgress(v, "Stealing") end end,
        SetState = function() end,
        Reset = function() if hud.setStealProgress then hud.setStealProgress(0, "Stealing") end end,
    }
end

--------------------------------------------------------------------------
-- Intro: the song is embedded (uploaded audio is private), written to a
-- file once and played through getcustomasset. Clip = 0:01 - 0:12 of the
-- track, so the drop at 0:06 lands at 5.0s into the clip.
--------------------------------------------------------------------------
local INTRO_MP3 = [==[]==]
local SONG_FILE, SONG_LEN, SONG_VOL = "fsocietyduels_intro_v1.mp3", 11, 2.5
local DROP = 5.0

local function decodeBase64(data)
	local map = {}
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	for i = 1, 64 do map[string.byte(chars, i)] = i - 1 end
	local out, chunk, n = {}, {}, 0
	for i = 1, #data - 3, 4 do
		local a, b, c, d = string.byte(data, i, i + 3)
		local va, vb, vc, vd = map[a], map[b], map[c], map[d]
		local v = va * 262144 + vb * 4096 + (vc or 0) * 64 + (vd or 0)
		n += 1
		chunk[n] = string.sub(string.char(v // 65536, (v // 256) % 256, v % 256), 1, vd and 3 or vc and 2 or 1)
		if n >= 4096 then
			table.insert(out, table.concat(chunk))
			chunk, n = {}, 0
		end
	end
	table.insert(out, table.concat(chunk))
	return table.concat(out)
end

local function loadSong()
	if not (writefile and getcustomasset) then return false end
	local ok, id = pcall(function()
		if not (isfile and isfile(SONG_FILE)) then writefile(SONG_FILE, decodeBase64(INTRO_MP3)) end
		return getcustomasset(SONG_FILE)
	end)
	if not ok or not id then return false end
	local snd = new("Sound", { SoundId = id, Volume = 0, Parent = sfxFolder })
	pcall(function() ContentProvider:PreloadAsync({ snd }) end)
	local t0 = os.clock()
	while not snd.IsLoaded and os.clock() - t0 < 4 do task.wait() end
	if not snd.IsLoaded then snd:Destroy() return false end
	return snd
end
local preloaded = nil -- nil = still loading, false = no song
task.spawn(function() preloaded = loadSong() end)

local function playIntro(done)
	local introGui = new("ScreenGui", { Name = "FsocietyIntro", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 200, ZIndexBehavior = Enum.ZIndexBehavior.Sibling, Parent = playerGui })
	local cover = new("CanvasGroup", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = C.Bg, Active = true, Parent = introGui })
	local stage = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(1280, 720), BackgroundTransparency = 1, Parent = cover })
	local stageScale = new("UIScale", { Parent = stage })
	local cam = workspace.CurrentCamera
	-- zoom is a NumberValue so it can be tweened on top of the screen fit
	local zoom = new("NumberValue", { Value = 1 })
	local function fit()
		local vp = cam and cam.ViewportSize or Vector2.new(1280, 720)
		stageScale.Scale = math.min(vp.X / 1280, vp.Y / 720) * zoom.Value
	end
	zoom.Changed:Connect(fit)
	introGui.Destroying:Connect(function() zoom:Destroy() end)
	fit()
	local fitConn = cam and cam:GetPropertyChangedSignal("ViewportSize"):Connect(fit)
	local CX, CY = 640, 360
	local function T(props)
		props.Parent = props.Parent or stage
		props.TextXAlignment = props.TextXAlignment or Enum.TextXAlignment.Center
		return text(props)
	end
	local function F(props, kids)
		props.BorderSizePixel = 0
		props.Parent = props.Parent or stage
		return new("Frame", props, kids)
	end

	-- faint scanlines and a glow that breathes with the beat
	local lines = F({ Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 30, Parent = cover })
	for y = 0, 1440, 4 do
		F({ Position = UDim2.fromOffset(0, y), Size = UDim2.new(1, 0, 0, 1), BackgroundColor3 = C.White, BackgroundTransparency = 0.98, ZIndex = 30, Parent = lines })
	end
	local glow = F({ AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(CX, CY), Size = UDim2.fromOffset(900, 900), BackgroundColor3 = Accent, BackgroundTransparency = 1, ZIndex = 1 }, { corner(450) })

	-- slow push-in: the stage creeps from 1.0 to 1.1 until the drop
	tween(zoom, DROP, { Value = 1.1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)

	----------------------------------------------------------------
	-- code rain: dim columns of characters, faster as the build-up grows
	----------------------------------------------------------------
	local GLYPHS = "01ABCDEF#$%&*+<>/\\=?{}[]fsociety"
	local function randomColumn(n)
		local t = {}
		for k = 1, n do
			local i = math.random(1, #GLYPHS)
			t[k] = string.sub(GLYPHS, i, i)
		end
		return table.concat(t, "\n")
	end
	local rain = {}
	local rainSpeed = 1
	for k = 1, 36 do
		local col = T({
			Text = randomColumn(40), Font = Enum.Font.Code, TextSize = 16,
			TextColor3 = C.Sub, TextTransparency = 1, TextYAlignment = Enum.TextYAlignment.Top,
			Position = UDim2.fromOffset((k - 1) * 36 + math.random(-6, 6), math.random(-900, -100)),
			Size = UDim2.fromOffset(20, 760), ZIndex = 2,
		})
		rain[k] = { Label = col, Speed = 60 + math.random() * 90, Alpha = 0.82 + math.random() * 0.12 }
	end
	local rainOn = true
	local rainConn = RunService.RenderStepped:Connect(function(dt)
		if not rainOn then return end
		for _, r in ipairs(rain) do
			local y = r.Label.Position.Y.Offset + r.Speed * rainSpeed * dt
			if y > 720 then
				y = -780
				r.Label.Text = randomColumn(40)
			end
			r.Label.Position = UDim2.fromOffset(r.Label.Position.X.Offset, y)
			if math.random() < 0.02 then r.Label.Text = randomColumn(40) end
		end
	end)
	introGui.Destroying:Connect(function() rainConn:Disconnect() end)
	for _, r in ipairs(rain) do tween(r.Label, 2, { TextTransparency = r.Alpha }, Enum.EasingStyle.Sine) end

	----------------------------------------------------------------
	-- dust: faint specks drifting sideways, so nothing is ever still
	----------------------------------------------------------------
	local dustOn = true
	task.spawn(function()
		while dustOn and introGui.Parent do
			local y = math.random(0, 720)
			local size = math.random(1, 3)
			local d = F({ AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(math.random(-40, 1320), y), Size = UDim2.fromOffset(size, size), BackgroundColor3 = C.White, BackgroundTransparency = 1, ZIndex = 4 }, { corner(2) })
			local dur = 4 + math.random() * 4
			tween(d, 0.8, { BackgroundTransparency = 0.6 + math.random() * 0.3 })
			tween(d, dur, { Position = UDim2.fromOffset(d.Position.X.Offset + math.random(-160, 160), y + math.random(-60, 60)) }, Enum.EasingStyle.Linear)
			task.delay(dur - 0.8, function() if d.Parent then tween(d, 0.8, { BackgroundTransparency = 1 }) end end)
			task.delay(dur, function() d:Destroy() end)
			task.wait(0.08)
		end
	end)

	-- the build-up speeds the rain up (called from the timeline)
	local function buildUp()
		task.spawn(function()
			local t0 = os.clock()
			while rainOn and os.clock() - t0 < 2.3 do
				rainSpeed = 1 + (os.clock() - t0) / 2.3 * 3
				task.wait()
			end
		end)
	end

	-- at the drop: the rain scatters, the zoom kicks
	local function fxDrop()
		rainOn = false
		for _, r in ipairs(rain) do
			local l = r.Label
			tween(l, 0.5, { Position = l.Position + UDim2.fromOffset(math.random(-120, 120), math.random(-60, 60)), TextTransparency = 1 }, Enum.EasingStyle.Quint)
		end
		zoom.Value = 1.18
		tween(zoom, 0.6, { Value = 1 }, Enum.EasingStyle.Back)
		-- dust stays, slower and fainter, under the title
	end

	local caret = T({ Text = "_", Font = Enum.Font.Code, TextSize = 40, TextColor3 = C.White, Position = UDim2.fromOffset(CX - 20, CY - 30), Size = UDim2.fromOffset(40, 60), ZIndex = 5 })

	-- title: main text plus red / cyan copies for the glitch
	local function titleSet(txt, size, y, col)
		local holder = F({ AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(CX, y), Size = UDim2.fromOffset(1200, size + 20), BackgroundTransparency = 1, ZIndex = 10 })
		local sc = new("UIScale", { Parent = holder })
		local r = T({ Text = txt, Font = Enum.Font.GothamBlack, TextSize = size, TextColor3 = Color3.fromRGB(255, 40, 60), TextTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 10, Parent = holder })
		local c = T({ Text = txt, Font = Enum.Font.GothamBlack, TextSize = size, TextColor3 = Color3.fromRGB(40, 230, 255), TextTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 10, Parent = holder })
		local m = T({ Text = txt, Font = Enum.Font.GothamBlack, TextSize = size, TextColor3 = col, TextTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 11, Parent = holder })
		return { Holder = holder, Scale = sc, R = r, C = c, M = m }
	end
	local fsoc = titleSet("", 110, CY - 40, C.White)
	local duels = titleSet("DUELS", 64, CY + 60, Accent)
	local names = T({ Text = "Malone   /   Murda", Font = Enum.Font.GothamBold, TextSize = 18, TextColor3 = C.Sub, TextTransparency = 1, Position = UDim2.fromOffset(CX - 400, CY + 120), Size = UDim2.fromOffset(800, 30), ZIndex = 10 })
	local bar = F({ AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(CX, CY + 20), Size = UDim2.fromOffset(0, 2), BackgroundColor3 = Accent, ZIndex = 10 })
	local flash = F({ Size = UDim2.fromScale(1, 1), BackgroundColor3 = C.White, BackgroundTransparency = 1, ZIndex = 40, Parent = cover })
	local hint = text({ Text = "DOUBLE CLICK TO SKIP", Font = Enum.Font.GothamBold, TextSize = 12, TextColor3 = C.Dim, TextXAlignment = Enum.TextXAlignment.Center, AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -24), Size = UDim2.fromOffset(300, 20), ZIndex = 45, Parent = cover })

	local function glitch(set, power)
		task.spawn(function()
			for _ = 1, 5 do
				local dx, dy = math.random(-power, power), math.random(-power // 2, power // 2)
				set.R.Position = UDim2.fromOffset(dx, dy)
				set.C.Position = UDim2.fromOffset(-dx, -dy)
				set.M.Position = UDim2.fromOffset(math.random(-2, 2), 0)
				task.wait(0.03)
			end
			set.R.Position = UDim2.fromOffset(2, 0)
			set.C.Position = UDim2.fromOffset(-2, 0)
			set.M.Position = UDim2.fromOffset(0, 0)
		end)
	end
	local function show(set, tr)
		set.M.TextTransparency = 0
		set.R.TextTransparency = tr or 0.45
		set.C.TextTransparency = tr or 0.45
	end
	local function shake(power, dur)
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < dur do
				local k = 1 - (os.clock() - t0) / dur
				stage.Position = UDim2.new(0.5, (math.random() - 0.5) * power * k, 0.5, (math.random() - 0.5) * power * k)
				task.wait()
			end
			stage.Position = UDim2.fromScale(0.5, 0.5)
		end)
	end
	local function pulse(k)
		glow.BackgroundTransparency = 0.9 - 0.04 * k
		tween(glow, 0.5, { BackgroundTransparency = 0.97 })
		fsoc.Scale.Scale = 1 + 0.04 * k
		tween(fsoc.Scale, 0.35, { Scale = 1 })
		duels.Scale.Scale = 1 + 0.06 * k
		tween(duels.Scale, 0.35, { Scale = 1 })
	end

	-- skipping and finishing
	local finished, skipped = false, false
	local song = nil
	local function finish()
		if finished then return end
		finished = true
		skipped = true
		if song then local s0 = song tween(s0, 0.6, { Volume = 0 }) task.delay(0.65, function() s0:Destroy() end) end
		tween(cover, 0.5, { GroupTransparency = 1 })
		task.wait(0.5)
		if fitConn then fitConn:Disconnect() end
		introGui:Destroy()
		done()
	end
	local lastClick = 0
	local skipConn = UserInputService.InputBegan:Connect(function(input)
		if finished then return end
		local k = input.KeyCode
		if k == Enum.KeyCode.Space or k == Enum.KeyCode.Return or k == Enum.KeyCode.Escape then task.spawn(finish) return end
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			if os.clock() - lastClick < 0.45 then task.spawn(finish) return end
			lastClick = os.clock()
			hint.Text = "CLICK AGAIN TO SKIP"
			hint.TextColor3 = C.White
			task.delay(0.45, function() if not finished then hint.Text = "DOUBLE CLICK TO SKIP" hint.TextColor3 = C.Dim end end)
		end
	end)
	introGui.Destroying:Connect(function() skipConn:Disconnect() end)
	task.delay(SONG_LEN + 6, function() if not finished then finish() end end)

	-- the clock follows the song so every hit lands
	local startClock = os.clock()
	local function now() return os.clock() - startClock end
	local function at(t)
		while not skipped and now() < t do task.wait() end
		return skipped
	end

	task.spawn(function()
		local ok, err = xpcall(function()
			local w0 = os.clock()
			while preloaded == nil and os.clock() - w0 < 5 do task.wait() end
			song = preloaded or nil
			preloaded = nil
			if song then
				song.Volume = SONG_VOL * (values["Volume"] / 100) * (values["Sounds"] and 1 or 0)
				song.TimePosition = 0
				song:Play()
				local p0 = os.clock()
				while song.TimePosition <= 0.001 and os.clock() - p0 < 1 do task.wait() end
				startClock = os.clock() - song.TimePosition
			else
				startClock = os.clock()
			end

			-- caret blinks in the dark
			task.spawn(function()
				while not finished and now() < 2.6 do
					caret.TextTransparency = 0 task.wait(0.3)
					caret.TextTransparency = 1 task.wait(0.25)
				end
				caret.TextTransparency = 1
			end)

			-- 2.69: FSOCIETY types in, a letter on each hit of the build-up
			if at(2.69) then return end
			buildUp()
			local WORD = "FSOCIETY"
			local hits = { 2.69, 3.1, 3.53, 3.85, 4.06, 4.32, 4.55, 4.81 }
			for i, t in ipairs(hits) do
				if at(t) then return end
				local s = string.sub(WORD, 1, i)
				fsoc.M.Text, fsoc.R.Text, fsoc.C.Text = s, s, s
				show(fsoc, 0.55)
				glitch(fsoc, 6 + i)
				play("Tick", 0.8 + i * 0.06)
			end

			-- 5.0: the drop. flash, shake, DUELS slams in
			if at(DROP) then return end
			flash.BackgroundTransparency = 0.15
			tween(flash, 0.45, { BackgroundTransparency = 1 })
			shake(24, 0.35)
			fxDrop()
			show(duels, 0.4)
			duels.Scale.Scale = 2.6
			tween(duels.Scale, 0.25, { Scale = 1 }, Enum.EasingStyle.Back)
			tween(bar, 0.4, { Size = UDim2.fromOffset(520, 2) })
			glitch(fsoc, 18)
			glitch(duels, 14)
			glow.BackgroundTransparency = 0.82
			tween(glow, 0.8, { BackgroundTransparency = 0.97 })

			if at(5.57) then return end
			pulse(0.8)
			glitch(duels, 8)
			tween(names, 0.6, { TextTransparency = 0 })

			for _, t in ipairs({ 6.1, 6.6, 7.1, 7.6, 8.1, 8.45, 9.17, 9.89 }) do
				if at(t) then return end
				local big = t >= 8.1
				pulse(big and 1.2 or 0.5)
				if big then glitch(fsoc, 12) glitch(duels, 10) shake(8, 0.15) end
			end

			-- fade out with the song, then the menu opens
			for _, set in ipairs({ fsoc, duels }) do
				for _, l in ipairs({ set.M, set.R, set.C }) do tween(l, 0.8, { TextTransparency = 1 }) end
				tween(set.Scale, 0.8, { Scale = 0.9 }, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
			end
			tween(names, 0.6, { TextTransparency = 1 })
			tween(bar, 0.6, { Size = UDim2.fromOffset(0, 2) })
			dustOn = false
			at(SONG_LEN - 0.4)
		end, debug.traceback)
		if not ok then warn("[Fsociety Duels] intro error: " .. tostring(err)) end
		finish()
	end)
end

introHooks.replay = function()
	if not preloaded then
		preloaded = nil
		task.spawn(function() preloaded = loadSong() end)
	end
	setVisible(false)
	task.wait(0.2)
	playIntro(function() setVisible(true) end)
end

--------------------------------------------------------------------------
-- Start
--------------------------------------------------------------------------
root.Visible = false
task.defer(function()
	RunService.RenderStepped:Wait() -- let the tab strip lay out first
	selectTab(tabs[1], true)
	setStatus("Hello, friend.")
	if values["Play intro"] then playIntro(function() setVisible(true) end) else setVisible(true) end
end)
writeConfig()